import fs from 'node:fs'
import path from 'node:path'

const FICHEROS = {
  "database/migrations/0059_corporate_tax_integration.sql": "-- =====================================================================\n-- 0059 · IMPUESTO SOBRE SOCIEDADES INTEGRADO: cierre, invariante, cuentas controladas, glosario y supuestos · v0.41.0\n-- ---------------------------------------------------------------------\n--   · Cierre: el asistente tiene el paso 10 «Impuesto sobre Sociedades» (antes de la regularización, que pasa a ser el\n--     11) y la vista previa del cierre avisa si falta: en modo ESTRICTO no deja cerrar (error); en GUIADO, aviso. Después\n--     de contabilizarlo, avisa si la 473 no ha quedado a cero.\n--   · Invariante 10: el gasto por impuesto de la contabilidad (630) = el de la declaración contabilizada. Con el\n--     invariante 4 (la 129 recibe el resultado de la PyG), la 129 = resultado antes de impuestos − (6300 + 6301).\n--   · Cuentas controladas: la 630 y la 474 solo las mueve el Impuesto sobre Sociedades. La 4752, la 4709 y la 473, no:\n--     el pago o el cobro de Hacienda y los pagos fraccionados se registran con un asiento.\n--   · Ajustes propuestos: el concepto ya no lleva importes con punto decimal (van en su columna).\n--   · Glosario: «Base imponible», «Diferencia temporaria», «Impuesto corriente» e «Impuesto diferido».\n--   · Base documental: la Ley 27/2014 con todos los artículos que se usan.\n--   · Catálogo de operaciones y Practicar: el impuesto del ejercicio y dos supuestos (corriente y diferido).\n-- Re-ejecutable.\n-- =====================================================================\n\n-- 1) Conceptos (generados desde frontend/src/glossary.js con frontend/tests/glossarySql.js)\ninsert into erp.concepts (key, sort, term, definition, example, term_en, definition_en, example_en, bc, sap, pgc) values\n('taxableBase', 550, 'Base imponible', 'El beneficio sobre el que se paga el Impuesto sobre Sociedades: el resultado contable más o menos los ajustes de lo que la ley del impuesto no deja deducir o deja deducir en otro año (art. 10.3 LIS), menos las bases negativas de años anteriores.', 'Resultado 182.000 + multa 1.000 + exceso de amortización 2.600 = base 185.600.', 'Taxable base', 'The profit on which corporate income tax is paid: the accounting profit plus or minus the adjustments for what the tax law does not allow to deduct, or allows in another year (art. 10.3 LIS), less tax losses from previous years.', 'Profit 182,000 + fine 1,000 + excess depreciation 2,600 = base 185,600.', 'Corporate income tax base (not standard: local add-ons)', 'Taxable income (tax provision)', '{630,4752}'),\n('temporaryDifference', 560, 'Diferencia temporaria', 'Un gasto o un ingreso que la contabilidad y el impuesto reconocen en años distintos: hoy no se deduce, pero se deducirá (o al revés). Genera un impuesto diferido; a diferencia de la permanente (una multa), revierte.', 'Amortización contable 5.000 y fiscal 2.400: 2.600 se deducirán en los años siguientes.', 'Temporary difference', 'An expense or income recognised by the accounts and by the tax in different years: not deductible today but deductible later (or the other way round). It creates a deferred tax; unlike a permanent difference (a fine), it reverses.', 'Accounting depreciation 5,000 and tax depreciation 2,400: 2,600 will be deducted in the following years.', 'Deferred tax (temporary difference)', 'Temporary difference (deferred taxes)', '{4740,479}'),\n('currentTax', 570, 'Impuesto corriente', 'El Impuesto sobre Sociedades que corresponde pagar por el ejercicio: la cuota íntegra. Se carga a la 6300; lo ya retenido o pagado a cuenta (473) se descuenta y queda la cuota diferencial, a pagar (4752) o a devolver (4709).', 'Cuota 37.976 con 10.000 pagados a cuenta: 6300 D 37.976 / 473 H 10.000 · 4752 H 27.976.', 'Current tax', 'The corporate income tax payable for the year: the gross tax. It is charged to 6300; what was withheld or paid on account (473) is deducted, leaving the amount payable (4752) or refundable (4709).', 'Tax 37,976 with 10,000 paid on account: 6300 Dr 37,976 / 473 Cr 10,000 · 4752 Cr 27,976.', 'Corporate income tax expense (current)', 'Current income tax', '{6300,4752,4709,473}'),\n('deferredTax', 580, 'Impuesto diferido', 'La parte del gasto por impuesto que se paga en otros años por las diferencias temporarias y las bases negativas (PGC, NRV 13.ª). Con él, el gasto del año no depende de cuándo se paga: activo 4740 / 4745 o pasivo 479 contra la 6301.', 'Diferencia temporaria de 2.600 al 21 %: 4740 D 546 / 6301 H 546.', 'Deferred tax', 'The part of the tax expense paid in other years because of temporary differences and tax losses (PGC, NRV 13.ª). With it, the expense of the year does not depend on when it is paid: asset 4740 / 4745 or liability 479 against 6301.', 'Temporary difference of 2,600 at 21 %: 4740 Dr 546 / 6301 Cr 546.', 'Deferred tax', 'Deferred taxes', '{6301,4740,4745,479}')\non conflict (key) do update set\n  sort = excluded.sort, term = excluded.term, definition = excluded.definition, example = excluded.example,\n  term_en = excluded.term_en, definition_en = excluded.definition_en, example_en = excluded.example_en,\n  bc = excluded.bc, sap = excluded.sap, pgc = excluded.pgc;\n\n-- 2) Fuente (generada desde frontend/src/sources.js con frontend/tests/sourcesSql.js)\ninsert into erp.sources (key, issuer, url, checked, title, ref, title_en, ref_en) values\n('lis', 'BOE', 'https://www.boe.es/eli/es/l/2014/11/27/27/con', '2026-10-20', 'Ley 27/2014, del Impuesto sobre Sociedades', 'Arts. 10 a 15 (base imponible, amortizaciones, deterioros, provisiones y gastos no deducibles), 26 (bases negativas), 29 y DT 44.ª (tipos) y 101 y 104 (reducida dimensión)', 'Law 27/2014 on Corporate Income Tax', 'Arts. 10 to 15 (taxable base, depreciation, impairments, provisions and non-deductible expenses), 26 (tax losses), 29 and DT 44.ª (rates) and 101 and 104 (reduced size)')\non conflict (key) do update set issuer = excluded.issuer, url = excluded.url, checked = excluded.checked, title = excluded.title,\n  ref = excluded.ref, title_en = excluded.title_en, ref_en = excluded.ref_en;\n\n-- 3) Cuentas controladas\ninsert into erp.control_rules (account_prefix, modules, side, note, note_en) values\n('630', '{corporate_tax}', 'both', 'Impuesto sobre beneficios: lo contabiliza el Impuesto sobre Sociedades del cierre.', 'Income tax: posted by the corporate income tax at year end.'),\n('474', '{corporate_tax}', 'both', 'Activos por impuesto diferido: los mueve el Impuesto sobre Sociedades.', 'Deferred tax assets: posted by the corporate income tax.')\non conflict (account_prefix) do update set modules = excluded.modules, side = excluded.side, note = excluded.note, note_en = excluded.note_en;\n\n-- 4) Catálogo de operaciones y supuestos\ninsert into erp.operations (key, sort, title, title_en, screen, entry, entry_en, accounts, concept, sources, description, description_en) values\n('corporate_tax', 175, 'Impuesto sobre Sociedades del ejercicio', 'Corporate income tax of the year', 'corporate_tax',\n '6300 D / 473 H · 4752 H (o 4709 D) · diferido: 4740 / 4745 / 6301', '6300 Dr / 473 Cr · 4752 Cr (or 4709 Dr) · deferred: 4740 / 4745 / 6301',\n '{630}', 'currentTax', '{lis,pgc}',\n 'Al cierre, antes de la regularización: del resultado contable a la base imponible, la cuota y lo que queda por pagar o devolver, con el impuesto diferido.',\n 'At year end, before closing the income statement: from the accounting profit to the taxable base, the tax and what remains to pay or be refunded, with deferred tax.')\non conflict (key) do update set sort = excluded.sort, title = excluded.title, title_en = excluded.title_en, screen = excluded.screen,\n  entry = excluded.entry, entry_en = excluded.entry_en, accounts = excluded.accounts, concept = excluded.concept,\n  sources = excluded.sources, description = excluded.description, description_en = excluded.description_en;\n\ninsert into erp.exercises (key, sort, level, operation, tax_type, title, title_en, statement, statement_en, expected, explanation, explanation_en, errors, sources, concept) values\n('corporate_tax_current', 150, 'advanced', 'corporate_tax', null, 'Impuesto sobre Sociedades del año', 'Corporate income tax of the year',\n 'Al cierre, la sociedad tiene una base imponible de 100.000 € y tributa al tipo general (25 %). Durante el año pagó 8.000 € a cuenta (pagos fraccionados, cuenta 473). Contabiliza el impuesto corriente.',\n 'At year end the company has a taxable base of €100,000 and pays the general rate (25 %). During the year it paid €8,000 on account (instalments, account 473). Record the current tax.',\n '[{\"account\": \"6300\", \"side\": \"debit\", \"amount\": 25000}, {\"account\": \"473\", \"side\": \"credit\", \"amount\": 8000}, {\"account\": \"4752\", \"side\": \"credit\", \"amount\": 17000}]',\n 'El gasto es la cuota: 25 % × 100.000 = 25.000 (6300, impuesto corriente). Lo pagado a cuenta (473) se descuenta y queda a ingresar la diferencia: 17.000 en la 4752, que se paga con el modelo 200 en julio.',\n 'The expense is the tax: 25 % × 100,000 = 25,000 (6300, current tax). What was paid on account (473) is deducted and the difference is payable: 17,000 in 4752, paid with form 200 in July.',\n '[{\"account\": \"4750\", \"side\": \"credit\", \"msg\": \"La 4750 es la deuda del IVA; la del Impuesto sobre Sociedades es la 4752.\", \"msg_en\": \"4750 is the VAT payable; corporate income tax payable is 4752.\"},\n   {\"account\": \"6301\", \"side\": \"debit\", \"msg\": \"La 6301 es el impuesto diferido; lo que corresponde pagar por el año es el impuesto corriente (6300).\", \"msg_en\": \"6301 is deferred tax; the tax payable for the year is current tax (6300).\"},\n   {\"account\": \"4709\", \"side\": \"debit\", \"msg\": \"Sale a pagar (25.000 > 8.000): la diferencia va a la 4752, no a la 4709.\", \"msg_en\": \"It is payable (25,000 > 8,000): the difference goes to 4752, not 4709.\"}]',\n '{lis,pgc}', 'currentTax'),\n('corporate_tax_deferred', 160, 'advanced', 'corporate_tax', null, 'Impuesto diferido por la amortización', 'Deferred tax from depreciation',\n 'La amortización contable de una máquina ha sido de 5.000 €, pero la ley del impuesto solo deja deducir 2.400 € este año (el máximo de la tabla). La diferencia se deducirá en los años siguientes. Con un tipo del 25 %, contabiliza el impuesto diferido.',\n 'The accounting depreciation of a machine was €5,000, but the tax law only allows €2,400 to be deducted this year (the table maximum). The difference will be deducted in the following years. At a 25 % rate, record the deferred tax.',\n '[{\"account\": \"4740\", \"side\": \"debit\", \"amount\": 650}, {\"account\": \"6301\", \"side\": \"credit\", \"amount\": 650}]',\n 'Los 2.600 de amortización que hoy no se deducen (art. 12.1.a LIS) se deducirán después: hoy se paga 2.600 × 25 % = 650 de más, que se recuperará. Es un activo por impuesto diferido (4740) que reduce el gasto por impuesto del año (6301 al Haber, NRV 13.ª).',\n 'The 2,600 of depreciation not deductible today (art. 12.1.a LIS) will be deducted later: 2,600 × 25 % = 650 more tax is paid today and will be recovered. It is a deferred tax asset (4740) that reduces the tax expense of the year (6301 credit, NRV 13.ª).',\n '[{\"account\": \"479\", \"side\": \"credit\", \"msg\": \"Pagas más impuesto ahora y menos después: es un activo (4740), no un pasivo (479).\", \"msg_en\": \"You pay more tax now and less later: it is an asset (4740), not a liability (479).\"},\n   {\"account\": \"6300\", \"side\": \"credit\", \"msg\": \"El impuesto diferido va a la 6301; la 6300 es el corriente.\", \"msg_en\": \"Deferred tax goes to 6301; 6300 is current tax.\"},\n   {\"account\": \"4745\", \"side\": \"debit\", \"msg\": \"La 4745 es el crédito por bases negativas; una diferencia temporaria va a la 4740.\", \"msg_en\": \"4745 is the credit for tax losses; a temporary difference goes to 4740.\"}]',\n '{lis,pgc}', 'deferredTax')\non conflict (key) do update set sort = excluded.sort, level = excluded.level, operation = excluded.operation, tax_type = excluded.tax_type,\n  title = excluded.title, title_en = excluded.title_en, statement = excluded.statement, statement_en = excluded.statement_en,\n  expected = excluded.expected, explanation = excluded.explanation, explanation_en = excluded.explanation_en,\n  errors = excluded.errors, sources = excluded.sources, concept = excluded.concept;\n\n-- 5) Ajustes propuestos con conceptos limpios (versión de la 0057; cambia solo el texto de los conceptos)\ncreate or replace function erp.corporate_tax_proposals(p_company uuid, p_year int)\nreturns table (origin text, source_id uuid, kind text, direction text, concept text, amount numeric, article text, included boolean)\nlanguage plpgsql stable as $$\ndeclare\n  v_fy erp.fiscal_years; v_erd boolean; v_debtors numeric;\n  a record; v_acc numeric; v_fm numeric; v_m numeric; v_pend numeric; v_inc numeric; v_dec numeric; v_disposed boolean;\n  i record; p record;\nbegin\n  if not erp.can_read(p_company) then raise exception 'Not allowed to read this company'; end if;\n  select * into v_fy from erp.fiscal_years where company_id = p_company and year = p_year;\n  if not found then raise exception 'No fiscal year % in this company', p_year; end if;\n  v_erd := (erp.corporate_tax_regime_hint(p_company, p_year)->>'is_erd')::boolean;\n\n  -- a) Amortización contable frente al máximo fiscal (art. 12.1.a). Meses de uso con la misma regla que la contable\n  --    (el primer mes, por días); el máximo, sobre el coste.\n  for a in select f.*, c.max_pct, c.code as class from erp.fixed_assets f join erp.depreciation_classes c on c.code = f.class_code\n           where f.company_id = p_company and f.start_date <= v_fy.ending_date loop\n    select coalesce(sum(d.amount), 0) into v_acc from erp.asset_depreciations d\n    where d.asset_id = a.id and d.period_end between v_fy.starting_date and v_fy.ending_date;\n    v_disposed := a.status = 'disposed' and a.disposal_date between v_fy.starting_date and v_fy.ending_date;\n    v_m := erp.asset_months_at(1200, a.start_date, least(v_fy.ending_date, coalesce(a.disposal_date, v_fy.ending_date)))\n         - case when a.start_date < v_fy.starting_date then erp.asset_months_at(1200, a.start_date, v_fy.starting_date - 1) else 0 end;\n    v_fm := round(erp.asset_cost_at(a.id, v_fy.ending_date) * a.max_pct / 100 * greatest(v_m, 0) / 12, 2);\n    v_pend := erp.corporate_tax_pending(p_company, 'depreciation', a.id, p_year);\n    if v_acc - v_fm >= 0.01 then\n      origin := 'depreciation'; source_id := a.id; kind := 'temporary'; direction := 'increase';\n      concept := format('Amortización por encima del máximo fiscal · %s %s (máximo de la tabla: %s %%)', a.code, a.name, trim_scale(a.max_pct));\n      amount := v_acc - v_fm; article := 'LIS art. 12.1.a'; included := true; return next;\n    elsif v_pend > 0 and (v_disposed or v_fm - v_acc >= 0.01) then\n      origin := 'depreciation'; source_id := a.id; kind := 'temporary'; direction := 'decrease';\n      concept := case when v_disposed then format('Reversión al dar de baja · %s %s', a.code, a.name)\n                      else format('Reversión: amortización contable por debajo del máximo fiscal · %s %s', a.code, a.name) end;\n      amount := case when v_disposed then v_pend else least(v_pend, v_fm - v_acc) end;\n      article := 'LIS art. 12.1.a'; included := true; return next;\n    end if;\n  end loop;\n\n  -- b) Deterioro del inmovilizado: no deducible (art. 13.2.a); revierte con su reversión o con la baja\n  for a in select f.* from erp.fixed_assets f where f.company_id = p_company\n           and exists (select 1 from erp.asset_events e where e.asset_id = f.id and e.kind in ('impairment', 'reversal')) loop\n    select coalesce(sum(e.amount) filter (where e.kind = 'impairment'), 0), coalesce(sum(e.amount) filter (where e.kind = 'reversal'), 0)\n      into v_inc, v_dec\n    from erp.asset_events e where e.asset_id = a.id and e.event_date between v_fy.starting_date and v_fy.ending_date;\n    v_pend := erp.corporate_tax_pending(p_company, 'asset_impairment', a.id, p_year);\n    v_disposed := a.status = 'disposed' and a.disposal_date between v_fy.starting_date and v_fy.ending_date;\n    if v_inc > 0 then\n      origin := 'asset_impairment'; source_id := a.id; kind := 'temporary'; direction := 'increase';\n      concept := format('Deterioro del inmovilizado · %s %s', a.code, a.name); amount := v_inc;\n      article := 'LIS art. 13.2.a'; included := true; return next;\n    end if;\n    v_dec := least(v_pend + v_inc, case when v_disposed then v_pend + v_inc else v_dec end);\n    if v_dec > 0 then\n      origin := 'asset_impairment'; source_id := a.id; kind := 'temporary'; direction := 'decrease';\n      concept := format('Reversión del deterioro%s · %s %s', case when v_disposed then ' (baja)' else '' end, a.code, a.name);\n      amount := v_dec; article := 'LIS art. 13.2.a'; included := true; return next;\n    end if;\n  end loop;\n\n  -- c) Deterioro de clientes (art. 13.1 y 104)\n  select coalesce(sum(o.pending), 0) into v_debtors from erp.open_items(p_company, v_fy.ending_date) o where o.invoice_type = 'sale';\n  for i in select ri.*, inv.due_date, inv.invoice_no from erp.receivable_impairments ri left join erp.invoices inv on inv.id = ri.invoice_id\n           where ri.company_id = p_company and ri.status <> 'cancelled' loop\n    if i.impair_date between v_fy.starting_date and v_fy.ending_date then\n      -- deterioro y fin en el mismo año: el gasto (694) y el ingreso (794) se compensan, no hay ajuste\n      continue when i.end_date is not null and i.end_date <= v_fy.ending_date;\n      if i.method = 'individual' and v_fy.ending_date < (i.due_date + interval '6 months')::date then\n        origin := 'receivable_impairment'; source_id := i.id; kind := 'temporary'; direction := 'increase';\n        concept := format('Deterioro %s · factura %s: no han pasado 6 meses desde el vencimiento (%s)', i.code, i.invoice_no,\n                          to_char(i.due_date, 'DD/MM/YYYY'));\n        amount := i.amount; article := 'LIS art. 13.1.a'; included := true; return next;\n      elsif i.method = 'global' and greatest(0, i.amount - case when v_erd then round(v_debtors * 0.01, 2) else 0 end) > 0 then\n        origin := 'receivable_impairment'; source_id := i.id; kind := 'temporary'; direction := 'increase';\n        concept := case when v_erd then format('Deterioro global %s por encima del 1 %% de los deudores', i.code)\n                        else format('Deterioro global %s: no deducible', i.code) end;\n        amount := i.amount - case when v_erd then round(v_debtors * 0.01, 2) else 0 end;\n        article := case when v_erd then 'LIS art. 13.1 y 104' else 'LIS art. 13.1' end; included := true; return next;\n      end if;\n    elsif i.impair_date < v_fy.starting_date then\n      v_pend := erp.corporate_tax_pending(p_company, 'receivable_impairment', i.id, p_year);\n      if v_pend > 0 and ((i.end_date is not null and i.end_date between v_fy.starting_date and v_fy.ending_date)\n                         or (i.status = 'active' and i.method = 'individual' and v_fy.ending_date >= (i.due_date + interval '6 months')::date)) then\n        origin := 'receivable_impairment'; source_id := i.id; kind := 'temporary'; direction := 'decrease';\n        concept := case when i.end_date is not null then format('Reversión: el deterioro %s se ha revertido o aplicado', i.code)\n                        else format('Reversión: el deterioro %s ya es deducible (6 meses desde el vencimiento)', i.code) end;\n        amount := v_pend; article := 'LIS art. 13.1'; included := true; return next;\n      end if;\n    end if;\n  end loop;\n\n  -- d) Provisiones (art. 14): dotaciones del año y, si ya se ajustaron antes, su reversión\n  for p in select pr.*, coalesce(sum(greatest(0, m.balance_after - m.balance_before)) filter (where m.kind in ('allocation', 'revision')), 0) as inc,\n                  coalesce(sum(greatest(0, m.balance_before - m.balance_after)) filter (where m.kind in ('revision', 'application')), 0) as dec\n           from erp.provisions pr\n           left join erp.provision_movements m on m.provision_id = pr.id and m.movement_date between v_fy.starting_date and v_fy.ending_date\n           where pr.company_id = p_company and pr.status <> 'cancelled'\n           group by pr.id loop\n    if p.inc > 0 then\n      origin := 'provision'; source_id := p.id; kind := 'temporary'; direction := 'increase';\n      concept := format('Provisión %s · %s', p.code, p.description); amount := p.inc;\n      article := case p.kind when 'commercial' then 'LIS art. 14.9 (garantías: límite por experiencia)'\n                             when 'taxes' then 'LIS art. 14 y 15 (deducible salvo el propio IS y las sanciones)'\n                             else 'LIS art. 14.1 (deducible si nace de una obligación legal o contractual)' end;\n      included := p.kind = 'commercial'; return next;\n    end if;\n    v_pend := erp.corporate_tax_pending(p_company, 'provision', p.id, p_year);\n    if p.dec > 0 and v_pend > 0 then\n      origin := 'provision'; source_id := p.id; kind := 'temporary'; direction := 'decrease';\n      concept := format('Reversión de la provisión %s (aplicada o revisada a la baja)', p.code); amount := least(v_pend, p.dec);\n      article := 'LIS art. 14'; included := true; return next;\n    end if;\n  end loop;\nend $$;\n\n-- 6) Invariante 10 (versión de la 0040 con el nuevo, al final)\ncreate or replace function erp.integrity_checks(p_company uuid, p_year int)\nreturns table (code text, sort int, status text, expected numeric, actual numeric, detail jsonb, title text, title_en text)\nlanguage plpgsql stable as $$\ndeclare\n  v_fy    erp.fiscal_years;\n  v_close erp.year_closings;\n  v_n     int;\n  v_a     numeric;\n  v_b     numeric;\n  v_c     numeric;\n  v_d     numeric;\n  v_det   jsonb;\n  v_cf    jsonb;\nbegin\n  select * into v_fy from erp.fiscal_years f where f.company_id = p_company and f.year = p_year;\n  if not found then return; end if;\n  select * into v_close from erp.year_closings y where y.company_id = p_company and y.fiscal_year_id = v_fy.id;\n\n  -- 1) Cada asiento cuadra\n  select count(*), coalesce(jsonb_agg(x.entry_no order by x.entry_no) filter (where x.rn <= 20), '[]')\n    into v_n, v_det\n  from (select e.entry_no, row_number() over (order by e.entry_no) rn\n        from erp.journal_entries e join erp.journal_lines l on l.entry_id = e.id\n        where e.company_id = p_company and e.fiscal_year_id = v_fy.id and e.status = 'posted'\n        group by e.id, e.entry_no having sum(l.debit) <> sum(l.credit)) x;\n  code := 'entries_balanced'; sort := 10; status := case when v_n = 0 then 'ok' else 'fail' end;\n  expected := 0; actual := v_n; detail := v_det;\n  title := 'Cada asiento cuadra (Debe = Haber)'; title_en := 'Every entry balances (debit = credit)';\n  return next;\n\n  -- 2) Sumas y saldos\n  select coalesce(sum(t.total_debit), 0), coalesce(sum(t.total_credit), 0) into v_a, v_b\n  from erp.trial_balance(p_company, p_year) t;\n  code := 'trial_balance'; sort := 20; status := case when v_a = v_b then 'ok' else 'fail' end;\n  expected := v_a; actual := v_b; detail := null;\n  title := 'Sumas y saldos: total Debe = total Haber'; title_en := 'Trial balance: total debits = total credits';\n  return next;\n\n  -- 3) Activo = Patrimonio neto + Pasivo\n  select coalesce(max(f.amount) filter (where f.code = 'ACT'), 0), coalesce(max(f.amount) filter (where f.code = 'PNP'), 0)\n    into v_a, v_b\n  from erp.financial_statement(p_company, p_year, 'balance') f;\n  code := 'balance_sheet'; sort := 30; status := case when v_a = v_b then 'ok' else 'fail' end;\n  expected := v_a; actual := v_b; detail := null;\n  title := 'Activo = Patrimonio neto + Pasivo'; title_en := 'Assets = Equity + Liabilities';\n  return next;\n\n  -- 4) Tras el cierre, la 129 recibe exactamente el resultado de la PyG\n  code := 'result_129'; sort := 40; title := 'La regularización lleva a la 129 el resultado de la PyG';\n  title_en := 'The closing of the P&L takes the P&L result to account 129'; detail := null;\n  if v_close.id is null or v_close.closing_pl_entry_id is null then\n    status := 'n/a'; expected := null; actual := null;\n  else\n    select coalesce(max(f.amount) filter (where f.code = 'PD'), 0) into v_a from erp.financial_statement(p_company, p_year, 'pyg') f;\n    select coalesce(sum(l.credit - l.debit), 0) into v_b\n    from erp.journal_lines l join erp.gl_accounts g on g.id = l.gl_account_id\n    where l.entry_id = v_close.closing_pl_entry_id and g.account_no like '129%';\n    status := case when v_a = v_b then 'ok' else 'fail' end; expected := v_a; actual := v_b;\n  end if;\n  return next;\n\n  -- 5) Apertura del año siguiente = cierre de este, cuenta a cuenta (cierre + apertura = 0)\n  code := 'opening_closing'; sort := 50; title := 'La apertura del año siguiente es el cierre de este, cuenta a cuenta';\n  title_en := 'Next year''s opening equals this year''s closing, account by account';\n  if v_close.id is null or v_close.closing_entry_id is null or v_close.opening_entry_id is null then\n    status := 'n/a'; expected := null; actual := null; detail := null;\n  else\n    select count(*), coalesce(jsonb_agg(x.account_no order by x.account_no) filter (where x.rn <= 20), '[]') into v_n, v_det\n    from (select g.account_no, row_number() over (order by g.account_no) rn\n          from erp.journal_lines l join erp.gl_accounts g on g.id = l.gl_account_id\n          where l.entry_id in (v_close.closing_entry_id, v_close.opening_entry_id)\n          group by g.account_no having sum(l.debit - l.credit) <> 0) x;\n    status := case when v_n = 0 then 'ok' else 'fail' end; expected := 0; actual := v_n; detail := v_det;\n  end if;\n  return next;\n\n  -- 6) Asiento + contraasiento = cero, cuenta a cuenta\n  select count(*), coalesce(jsonb_agg(x.entry_no order by x.entry_no) filter (where x.rn <= 20), '[]') into v_n, v_det\n  from (select o.entry_no, row_number() over (order by o.entry_no) rn\n        from erp.journal_entries r\n        join erp.journal_entries o on o.id = r.reversal_of\n        where r.company_id = p_company and r.fiscal_year_id = v_fy.id and r.status = 'posted'\n          and exists (select 1 from erp.journal_lines l where l.entry_id in (r.id, o.id)\n                      group by l.gl_account_id having sum(l.debit - l.credit) <> 0)) x;\n  code := 'reversals_zero'; sort := 60; status := case when v_n = 0 then 'ok' else 'fail' end;\n  expected := 0; actual := v_n; detail := v_det;\n  title := 'Un asiento y su contraasiento suman cero'; title_en := 'An entry and its reversal add up to zero';\n  return next;\n\n  -- 7) La línea del tercero de cada factura = total − retención (recibida: Haber · emitida: Debe)\n  select count(*), coalesce(jsonb_agg(x.invoice_no order by x.invoice_no) filter (where x.rn <= 20), '[]') into v_n, v_det\n  from (select i.invoice_no, row_number() over (order by i.invoice_no) rn\n        from erp.invoices i\n        join erp.business_partners bp on bp.id = i.partner_id\n        where i.company_id = p_company and i.fiscal_year_id = v_fy.id\n          and (select coalesce(sum(l.debit - l.credit), 0) from erp.journal_lines l\n               where l.entry_id = i.entry_id and l.gl_account_id = bp.gl_account_id)\n              <> (i.total_amount - i.withholding_amount) * case i.invoice_type when 'sale' then 1 else -1 end) x;\n  code := 'invoice_partner'; sort := 70; status := case when v_n = 0 then 'ok' else 'fail' end;\n  expected := 0; actual := v_n; detail := v_det;\n  title := 'En cada factura, el tercero queda por el total menos la retención';\n  title_en := 'In every invoice, the partner is posted at total minus withholding';\n  return next;\n\n  -- 8) 472 / 477 de los asientos de las facturas = cuotas del libro registro\n  --    477: repercutido de las ventas + recargo de equivalencia + autorrepercusión (ISP, adquisición intracomunitaria)\n  --    472: soportado deducible de las compras (con prorrata, solo la parte deducible)\n  select coalesce(sum(case when g.account_no like '477%' then l.credit - l.debit else 0 end), 0),\n         coalesce(sum(case when g.account_no like '472%' then l.debit - l.credit else 0 end), 0)\n    into v_a, v_b\n  from erp.invoices i\n  join erp.journal_lines l on l.entry_id = i.entry_id\n  join erp.gl_accounts g on g.id = l.gl_account_id\n  where i.company_id = p_company and i.fiscal_year_id = v_fy.id;\n  select coalesce(sum(case when r.invoice_type = 'sale' then r.tax_amount + coalesce(r.surcharge_amount, 0)\n                           when r.rate_category in ('reverse_charge', 'intra_eu_acquisition') then r.tax_amount\n                           else 0 end), 0),\n         coalesce(sum(case when r.invoice_type = 'purchase' then r.deductible_amount else 0 end), 0)\n    into v_c, v_d\n  from erp.v_invoice_register r where r.company_id = p_company and r.fiscal_year = p_year;\n  code := 'tax_register'; sort := 80;\n  status := case when v_a = v_c and v_b = v_d then 'ok' else 'fail' end;\n  expected := v_c + v_d; actual := v_a + v_b;\n  detail := jsonb_build_object('ledger_477', v_a, 'register_output', v_c, 'ledger_472', v_b, 'register_input', v_d);\n  title := 'Las 472 / 477 de las facturas = las cuotas del libro registro';\n  title_en := 'Invoice 472 / 477 postings = the VAT register amounts';\n  return next;\n\n  -- 9) Variación de la tesorería = EFE directo = EFE indirecto\n  v_cf := erp.cash_flow_check(p_company, p_year);\n  v_a := (v_cf->>'cash_change')::numeric;\n  v_b := (v_cf->'indirect'->>'total')::numeric;\n  v_c := (v_cf->'direct'->>'total')::numeric;\n  code := 'cash_flow'; sort := 90; status := case when v_a = v_b and v_a = v_c then 'ok' else 'fail' end;\n  expected := v_a; actual := v_b; detail := jsonb_build_object('cash_change', v_a, 'indirect', v_b, 'direct', v_c);\n  title := 'Variación de la tesorería (57) = EFE directo = EFE indirecto';\n  title_en := 'Change in cash (57) = direct cash flow = indirect cash flow';\n  return next;\n\n  -- 10) v0.41.0 · Gasto por impuesto en la contabilidad (630) = el de la declaración contabilizada (corriente + diferido)\n  --     Con la regularización, la 129 recibe el resultado antes de impuestos menos ese gasto (invariante 4).\n  select (r.result->>'tax_expense')::numeric into v_c from erp.corporate_tax_returns r\n  where r.fiscal_year_id = v_fy.id and r.status = 'posted';\n  code := 'corporate_tax'; sort := 100;\n  if v_c is null then\n    status := 'n/a'; expected := null; actual := null; detail := null;\n  else\n    select coalesce(sum(l.debit - l.credit), 0) into v_a\n    from erp.journal_lines l join erp.journal_entries e on e.id = l.entry_id join erp.gl_accounts g on g.id = l.gl_account_id\n    where e.company_id = p_company and e.fiscal_year_id = v_fy.id and e.status = 'posted'\n      and e.entry_type not in ('closing_pl', 'closing') and g.account_no like '630%';\n    status := case when v_a = v_c then 'ok' else 'fail' end; expected := v_c; actual := v_a;\n    detail := jsonb_build_object('ledger_630', v_a, 'return_tax_expense', v_c);\n  end if;\n  title := 'Gasto por impuesto (630) = el de la declaración del Impuesto sobre Sociedades';\n  title_en := 'Income tax expense (630) = the corporate income tax return';\n  return next;\nend $$;\n\n-- 7) Vista previa del cierre (versión de la 0048, marcado «v0.41.0»)\nCREATE OR REPLACE FUNCTION erp.year_closing_preview(p_company uuid, p_year integer)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE\nAS $function$\ndeclare\n  v_fy       erp.fiscal_years;\n  v_prev     erp.fiscal_years;\n  v_next     erp.fiscal_years;\n  v_done     erp.year_closings;\n  v_checks   jsonb := '[]';\n  v_n        int;\n  v_txt      text;\n  v_result   numeric;\n  v_res_no   text := erp.result_account_no(p_company);\n  v_pl       jsonb;\n  v_close    jsonb;\nbegin\n  select * into v_fy from erp.fiscal_years where company_id = p_company and year = p_year;\n  if not found then\n    raise exception 'Fiscal year % does not exist', p_year;\n  end if;\n  select * into v_prev from erp.fiscal_years where company_id = p_company and year = p_year - 1;\n  select * into v_next from erp.fiscal_years where company_id = p_company and year = p_year + 1;\n  select * into v_done from erp.year_closings where fiscal_year_id = v_fy.id and status = 'posted';\n\n  -- 1) COMPROBACIONES · error = impide cerrar · warning = hay que aceptarlo · info = solo informa\n  if v_prev.id is not null and v_prev.status = 'open'\n     and exists (select 1 from erp.journal_entries where fiscal_year_id = v_prev.id and status = 'posted') then\n    v_checks := v_checks || jsonb_build_object('code', 'previous_year_open', 'severity', 'error', 'detail', p_year - 1);\n  end if;\n\n  select count(*) into v_n from erp.journal_entries where fiscal_year_id = v_fy.id and status = 'draft';\n  if v_n > 0 then\n    v_checks := v_checks || jsonb_build_object('code', 'draft_entries', 'severity', 'error', 'detail', v_n);\n  end if;\n\n  -- Trimestres de IVA / IGIC sin liquidar (después del cierre ya no se podrán contabilizar)\n  select string_agg(x.tax || ' ' || x.q || 'T', ', ' order by x.tax, x.q) into v_txt\n  from (select case s.tax_type when 'VAT' then 'IVA' else 'IGIC' end as tax, q\n        from erp.tax_settlement_setup s cross join generate_series(1, 4) q\n        where s.company_id = p_company\n          and not exists (select 1 from erp.tax_settlements t\n                          where t.company_id = p_company and t.tax_type = s.tax_type\n                            and t.year = p_year and t.quarter = q and t.status = 'posted')) x;\n  if v_txt is not null then\n    v_checks := v_checks || jsonb_build_object('code', 'unsettled_quarters', 'severity', 'warning', 'detail', v_txt);\n  end if;\n\n  -- Saldos anómalos graves (p. ej. caja acreedora): se arrastrarían al año siguiente\n  select string_agg(a.account_no, ', ' order by a.account_no) into v_txt\n  from erp.balance_anomalies(p_company, p_year) a where a.severity = 'error';\n  if v_txt is not null then\n    v_checks := v_checks || jsonb_build_object('code', 'anomalies', 'severity', 'warning', 'detail', v_txt);\n  end if;\n\n  -- v0.35.0 · Inmovilizado sin amortizar hasta el final del ejercicio (la amortización es un gasto del año: NRV 2.ª)\n  select string_agg(a.code, ', ' order by a.code) into v_txt\n  from erp.fixed_assets a\n  where a.company_id = p_company and a.status = 'active' and a.start_date <= v_fy.ending_date\n    and erp.asset_depr_at(a.id, v_fy.ending_date) > erp.asset_posted(a.id);\n  if v_txt is not null then\n    v_checks := v_checks || jsonb_build_object('code', 'assets_not_depreciated', 'severity', 'warning', 'detail', v_txt);\n  end if;\n\n  -- v0.36.0 · Periodificaciones de un ejercicio anterior sin revertir (el gasto o el ingreso se quedaría en el balance)\n  select string_agg(a.code, ', ' order by a.code) into v_txt\n  from erp.accruals a\n  where a.company_id = p_company and a.status = 'active' and a.cutoff_date < v_fy.starting_date;\n  if v_txt is not null then\n    v_checks := v_checks || jsonb_build_object('code', 'accruals_unreversed', 'severity', 'warning', 'detail', v_txt);\n  end if;\n\n  -- v0.37.0 · Inventario sin contabilizar (hay existencias o compras de aprovisionamientos) y provisiones sin revisar\n  if not exists (select 1 from erp.inventory_counts c where c.fiscal_year_id = v_fy.id and c.status = 'posted')\n     -- (solo si la empresa tiene cuentas de existencias: una de servicios con alguna compra suelta no tiene almacén)\n     and exists (select 1 from erp.gl_accounts g where g.company_id = p_company and g.account_type = 'posting' and g.account_no ~ '^3[0-6]') then\n    v_checks := v_checks || jsonb_build_object('code', 'inventory_not_counted', 'severity', 'warning', 'detail', p_year);\n  end if;\n  select string_agg(pv.code, ', ' order by pv.code) into v_txt\n  from erp.provisions pv\n  where pv.company_id = p_company and pv.status = 'active'\n    and exists (select 1 from erp.provision_movements m where m.provision_id = pv.id and m.movement_date < v_fy.starting_date)\n    and not exists (select 1 from erp.provision_movements m where m.provision_id = pv.id\n                    and m.movement_date between v_fy.starting_date and v_fy.ending_date);\n  if v_txt is not null then\n    v_checks := v_checks || jsonb_build_object('code', 'provisions_not_reviewed', 'severity', 'warning', 'detail', v_txt);\n  end if;\n\n  -- v0.41.0 · Impuesto sobre Sociedades: va antes de la regularización (en modo estricto, sin él no se cierra)\n  if v_fy.status = 'open' and erp.pre_tax_result(p_company, v_fy.id) <> 0\n     and not exists (select 1 from erp.corporate_tax_returns r where r.fiscal_year_id = v_fy.id and r.status = 'posted') then\n    v_checks := v_checks || jsonb_build_object('code', 'corporate_tax_missing',\n      'severity', case when (select control_mode from erp.companies where id = p_company) = 'strict' then 'error' else 'warning' end,\n      'detail', p_year);\n  end if;\n  -- …y después de contabilizarlo, la 473 (retenciones y pagos a cuenta) tiene que quedar a cero\n  if v_fy.status = 'open' and exists (select 1 from erp.corporate_tax_returns r where r.fiscal_year_id = v_fy.id and r.status = 'posted') then\n    select string_agg(g.account_no, ', ') into v_txt from (\n      select g.account_no from erp.journal_lines l join erp.journal_entries e on e.id = l.entry_id join erp.gl_accounts g on g.id = l.gl_account_id\n      where e.company_id = p_company and e.fiscal_year_id = v_fy.id and e.status = 'posted' and e.entry_type not in ('closing_pl', 'closing')\n        and g.account_no like '473%' group by g.account_no having sum(l.debit - l.credit) <> 0) g;\n    if v_txt is not null then\n      v_checks := v_checks || jsonb_build_object('code', 'withholdings_left', 'severity', 'warning', 'detail', v_txt);\n    end if;\n  end if;\n\n  if not exists (select 1 from erp.gl_accounts where company_id = p_company and account_no = v_res_no) then\n    v_checks := v_checks || jsonb_build_object('code', 'result_account_created', 'severity', 'info', 'detail', v_res_no);\n  end if;\n  if v_next.id is null then\n    v_checks := v_checks || jsonb_build_object('code', 'next_year_created', 'severity', 'info', 'detail', p_year + 1);\n  elsif v_next.status = 'closed' then\n    v_checks := v_checks || jsonb_build_object('code', 'next_year_closed', 'severity', 'error', 'detail', p_year + 1);\n  end if;\n\n  -- 2) REGULARIZACIÓN: cada cuenta de gastos e ingresos se salda al lado contrario; la diferencia, a la 129\n  select -coalesce(sum(b.balance), 0),\n         coalesce(jsonb_agg(jsonb_build_object('account_no', b.account_no, 'account_name', b.account_name,\n                    'debit', greatest(-b.balance, 0), 'credit', greatest(b.balance, 0)) order by b.account_no), '[]')\n    into v_result, v_pl\n  from erp.year_account_balances(v_fy.id) b\n  where left(b.account_no, 1) in ('6', '7');\n  if v_result <> 0 then\n    v_pl := v_pl || jsonb_build_object('account_no', v_res_no, 'account_name', 'Resultado del ejercicio',\n                      'debit', greatest(-v_result, 0), 'credit', greatest(v_result, 0));\n  end if;\n\n  -- 3) CIERRE: saldos de balance (grupos 1 a 5) después de la regularización, saldados al lado contrario\n  select coalesce(jsonb_agg(jsonb_build_object('account_no', c.account_no, 'account_name', c.account_name,\n                    'debit', greatest(-c.balance, 0), 'credit', greatest(c.balance, 0)) order by c.account_no), '[]')\n    into v_close\n  from (\n    select b.account_no, b.account_name,\n           b.balance + case when b.account_no = v_res_no then -v_result else 0 end as balance\n    from erp.year_account_balances(v_fy.id) b\n    where left(b.account_no, 1) between '1' and '5'\n    union all   -- la 129 aún sin movimientos\n    select v_res_no, 'Resultado del ejercicio', -v_result\n    where v_result <> 0\n      and not exists (select 1 from erp.year_account_balances(v_fy.id) b where b.account_no = v_res_no)\n  ) c\n  where c.balance <> 0;\n\n  return jsonb_build_object(\n    'year', p_year, 'status', v_fy.status,\n    'closing_date', v_fy.ending_date, 'opening_date', v_fy.ending_date + 1,\n    'checks', v_checks,\n    'can_close', v_fy.status = 'open' and not exists (select 1 from jsonb_array_elements(v_checks) c where c->>'severity' = 'error'),\n    'has_warnings', exists (select 1 from jsonb_array_elements(v_checks) c where c->>'severity' = 'warning'),\n    'result', coalesce(v_done.result, v_result),\n    'result_account_no', v_res_no,\n    'closing_pl_lines', v_pl,\n    'closing_lines', v_close,\n    'closed', v_done.id is not null,\n    'closing_id', v_done.id,\n    'entries', case when v_done.id is null then null else jsonb_build_object(\n       'closing_pl', (select entry_no from erp.journal_entries where id = v_done.closing_pl_entry_id),\n       'closing',    (select entry_no from erp.journal_entries where id = v_done.closing_entry_id),\n       'opening',    (select entry_no from erp.journal_entries where id = v_done.opening_entry_id)) end,\n    'can_reopen', v_done.id is not null and coalesce(v_next.status, 'open') = 'open');\nend $function$\n;\n\n-- 8) Asistente de cierre (versión de la 0048 con el paso 10 nuevo)\ncreate or replace function erp.closing_checklist(p_company uuid, p_year int)\nreturns table (step int, code text, status text, detail jsonb, screen text)\nlanguage plpgsql stable as $$\ndeclare\n  v_fy    erp.fiscal_years;\n  v_type  text := (select case c.tax_territory when 'canary_islands' then 'IGIC' else 'VAT' end from erp.companies c where c.id = p_company);\n  v_n     int;\n  v_m     int;\n  v_txt   text;\nbegin\n  select * into v_fy from erp.fiscal_years where company_id = p_company and year = p_year;\n  if not found or not erp.can_read(p_company) then return; end if;\n\n  -- 1) Liquidaciones de IVA / IGIC de los cuatro trimestres\n  select count(*) into v_n from erp.tax_settlements s\n  where s.company_id = p_company and s.year = p_year and s.status = 'posted' and s.tax_type = v_type;\n  select count(*) into v_m from erp.invoices i where i.company_id = p_company and i.fiscal_year_id = v_fy.id;\n  step := 1; code := 'settlements'; screen := 'settlement';\n  status := case when v_n >= 4 then 'done' when v_m = 0 and v_n = 0 then 'na' else 'pending' end;\n  detail := jsonb_build_object('settled', v_n, 'tax', v_type); return next;\n\n  -- 2) Periodificaciones del año anterior revertidas\n  select count(*) into v_n from erp.accruals a where a.company_id = p_company and a.status = 'active' and a.cutoff_date < v_fy.starting_date;\n  step := 2; code := 'accruals_reversed'; screen := 'adjustments';\n  status := case when v_n = 0 then 'done' else 'pending' end; detail := jsonb_build_object('pending', v_n); return next;\n\n  -- 3) Amortización del inmovilizado hasta el 31/12\n  select count(*), count(*) filter (where erp.asset_depr_at(a.id, v_fy.ending_date) > erp.asset_posted(a.id)) into v_m, v_n\n  from erp.fixed_assets a where a.company_id = p_company and a.status = 'active' and a.start_date <= v_fy.ending_date;\n  step := 3; code := 'depreciation'; screen := 'assets';\n  status := case when v_m = 0 then 'na' when v_n = 0 then 'done' else 'pending' end;\n  detail := jsonb_build_object('assets', v_m, 'pending', v_n); return next;\n\n  -- 4) Deterioro del inmovilizado: el valor recuperable lo estima la empresa\n  step := 4; code := 'asset_impairment'; screen := 'assets';\n  status := case when v_m = 0 then 'na' else 'review' end;\n  detail := jsonb_build_object('impaired', (select count(distinct ev.asset_id) from erp.asset_events ev join erp.fixed_assets a on a.id = ev.asset_id\n                                            where ev.company_id = p_company and ev.kind = 'impairment' and a.status = 'active')); return next;\n\n  -- 5) Periodificaciones del cierre (las de este año)\n  select count(*) into v_n from erp.accruals a where a.company_id = p_company and a.status <> 'cancelled'\n    and a.cutoff_date between v_fy.starting_date and v_fy.ending_date;\n  step := 5; code := 'accruals'; screen := 'adjustments';\n  status := case when v_n > 0 then 'done' else 'review' end; detail := jsonb_build_object('accruals', v_n); return next;\n\n  -- 6) Deterioro de clientes: vencidas hace más de 6 meses sin deterioro, y deterioros de facturas ya cobradas\n  select count(*) into v_n from erp.open_items(p_company, v_fy.ending_date) o\n  where o.invoice_type = 'sale' and o.pending > 0 and o.due_date + interval '6 months' <= v_fy.ending_date\n    and not exists (select 1 from erp.receivable_impairments i where i.invoice_id = o.invoice_id and i.status = 'active');\n  select count(*) into v_m from erp.receivable_impairments i join erp.open_items(p_company, v_fy.ending_date) o on o.invoice_id = i.invoice_id\n  where i.company_id = p_company and i.status = 'active' and i.method = 'individual' and o.pending <= 0;\n  step := 6; code := 'bad_debts'; screen := 'adjustments';\n  status := case when v_m > 0 then 'pending' when v_n > 0 then 'review' else 'done' end;\n  detail := jsonb_build_object('overdue_6m', v_n, 'collected', v_m); return next;\n\n  -- 7) Provisiones revisadas este año\n  select count(*), count(*) filter (where not exists (select 1 from erp.provision_movements m where m.provision_id = pv.id\n                                                      and m.movement_date between v_fy.starting_date and v_fy.ending_date))\n  into v_m, v_n from erp.provisions pv where pv.company_id = p_company and pv.status = 'active'\n    and exists (select 1 from erp.provision_movements m where m.provision_id = pv.id and m.movement_date <= v_fy.ending_date);\n  step := 7; code := 'provisions'; screen := 'adjustments';\n  status := case when v_m = 0 then 'review' when v_n = 0 then 'done' else 'pending' end;\n  detail := jsonb_build_object('active', v_m, 'not_reviewed', v_n); return next;\n\n  -- 8) Inventario del cierre (si hay existencias o compras de aprovisionamientos)\n  select count(*) into v_n from erp.inventory_counts c where c.fiscal_year_id = v_fy.id and c.status = 'posted';\n  -- v0.37.0 (0048): con cuentas de existencias, falta; sin ellas pero con compras de aprovisionamientos, revisar\n  select count(*) into v_m from erp.gl_accounts g where g.company_id = p_company and g.account_type = 'posting' and g.account_no ~ '^3[0-6]';\n  step := 8; code := 'inventory'; screen := 'adjustments';\n  status := case when v_n > 0 then 'done' when v_m > 0 then 'pending'\n                 when exists (select 1 from erp.journal_lines l join erp.journal_entries e on e.id = l.entry_id\n                              join erp.gl_accounts g on g.id = l.gl_account_id\n                              where e.fiscal_year_id = v_fy.id and e.status = 'posted' and g.account_no ~ '^60[0-2]') then 'review'\n                 else 'na' end;\n  detail := jsonb_build_object('posted', v_n > 0); return next;\n\n  -- 9) Comprobaciones del auditor sin avisos ni errores\n  select count(*), string_agg(c.code, ', ' order by c.sort) into v_n, v_txt\n  from erp.run_audit_checks(p_company, p_year, v_fy.ending_date) c where c.status in ('warning', 'error');\n  step := 9; code := 'audit_checks'; screen := 'checks';\n  status := case when v_n = 0 then 'done' else 'pending' end; detail := jsonb_build_object('open', v_n, 'codes', v_txt); return next;\n\n  -- 10) v0.41.0 · Impuesto sobre Sociedades (antes de la regularización)\n  step := 10; code := 'corporate_tax'; screen := 'corporate_tax';\n  status := case when exists (select 1 from erp.corporate_tax_returns r where r.fiscal_year_id = v_fy.id and r.status = 'posted') then 'done'\n                 when erp.pre_tax_result(p_company, v_fy.id) = 0 then 'na' else 'pending' end;\n  detail := jsonb_build_object('pre_tax_result', erp.pre_tax_result(p_company, v_fy.id)); return next;\n\n  -- 11) Cierre del ejercicio (regularización, cierre y apertura)\n  step := 11; code := 'close'; screen := 'closing';\n  status := case when v_fy.status = 'closed' then 'done' else 'pending' end;\n  detail := jsonb_build_object('fiscal_year_status', v_fy.status); return next;\nend $$;\n",
  "database/tests/test_fase54_corporate_tax_integration.sql": "-- =====================================================================\n-- PRUEBAS FASE 54 · Impuesto sobre Sociedades integrado (migración 0059 · v0.41.0)\n-- ---------------------------------------------------------------------\n--   · Cierre: sin el impuesto contabilizado, la vista previa avisa (guiado) o no deja cerrar (estricto); el asistente\n--     tiene el paso 10 «Impuesto sobre Sociedades» y el cierre pasa al 11; después, la 473 tiene que quedar a cero.\n--   · Invariante 10: 630 de la contabilidad = gasto de la declaración. Con la regularización:\n--     la 129 = resultado antes de impuestos − (6300 + 6301). Supuesto: beneficio 40.000, pagos a cuenta 3.000,\n--     tipo general 25 % → 6300 10.000 / 473 3.000 · 4752 7.000; la 129 = 40.000 − 10.000 = 30.000.\n--   · Cuentas controladas: 630 y 474 (en estricto, un asiento manual a la 630 no se contabiliza).\n--   · Conceptos de los ajustes sin importes con punto decimal; glosario, fuente y los dos supuestos nuevos.\n-- =====================================================================\n\\set ON_ERROR_STOP 1\n\\set QUIET 1\n\ninsert into auth.users (id, email) values ('00000000-0000-0000-0000-0000000000a1', 'admin@test.local');\ninsert into erp.app_profiles (user_id, app_role, max_companies) values ('00000000-0000-0000-0000-0000000000a1', 'owner', null);\n\ncreate or replace function public.falla(sql text, texto text) returns boolean language plpgsql as $$\nbegin\n  execute sql;\n  return false;\nexception when others then\n  if sqlerrm ilike '%' || texto || '%' then return true; end if;\n  raise notice 'error inesperado: %', sqlerrm;\n  return false;\nend $$;\ncreate or replace function public.empresa(nombre text) returns uuid language plpgsql as $$\ndeclare e uuid; c text;\nbegin\n  insert into erp.companies (name, industry, tax_territory, created_by) values (nombre, 'services', 'mainland', auth.uid()) returning id into e;\n  perform erp.create_fiscal_year(e, 2026); perform erp.create_fiscal_year(e, 2027);\n  perform erp.setup_taxes(e);\n  foreach c in array array['57200001:Banco', '70500001:Prestación de servicios', '62900001:Otros servicios',\n                           '47300001:HP retenciones y pagos a cuenta', '21300001:Maquinaria', '63000001:Impuesto corriente',\n                           '47520001:HP acreedora por IS'] loop\n    if not exists (select 1 from erp.gl_accounts where company_id = e and account_no = split_part(c, ':', 1)) then\n      perform erp.create_posting_account(e, split_part(c, ':', 1), split_part(c, ':', 2));\n    end if;\n  end loop;\n  return e;\nend $$;\ncreate or replace function public.manual(e uuid, d date, l jsonb) returns void language plpgsql as $$\ndeclare a uuid;\nbegin\n  insert into erp.journal_entries (company_id, fiscal_year_id, posting_date, description)\n  values (e, (select id from erp.fiscal_years where company_id = e and year = extract(year from d)), d, 'Supuesto') returning id into a;\n  insert into erp.journal_lines (entry_id, company_id, line_no, gl_account_id, debit, credit)\n  select a, e, x.ord, (select id from erp.gl_accounts where company_id = e and account_no = x.v->>0), (x.v->>1)::numeric, (x.v->>2)::numeric\n  from jsonb_array_elements(l) with ordinality as x(v, ord);\n  perform erp.post_entry(a);\n  execute 'set constraints all immediate';   -- la regla de las cuentas controladas es diferida: se comprueba aquí\n  execute 'set constraints all deferred';\nend $$;\ncreate or replace function public.chk(e uuid, y int, c text) returns text language sql as $$\n  select x->>'severity' from jsonb_array_elements(erp.year_closing_preview(e, y)->'checks') x where x->>'code' = c;\n$$;\ncreate or replace function public.saldo(e uuid, y int, cta text) returns numeric language sql as $$\n  select coalesce(sum(l.credit - l.debit), 0) from erp.journal_lines l join erp.journal_entries j on j.id = l.entry_id\n  join erp.gl_accounts g on g.id = l.gl_account_id join erp.fiscal_years f on f.id = j.fiscal_year_id\n  where j.company_id = e and f.year = y and j.status = 'posted' and g.account_no like cta || '%' and j.entry_type <> 'closing';\n$$;\ncreate or replace function public.resp(t text) returns jsonb language sql as $$\n  select jsonb_agg(jsonb_build_object('account_no', p[1], 'debit', case p[2] when 'D' then p[3]::numeric else 0 end,\n                                      'credit', case p[2] when 'H' then p[3]::numeric else 0 end) order by ord)\n  from unnest(string_to_array(t, ' | ')) with ordinality u(x, ord), string_to_array(u.x, ' ') p;\n$$;\ngrant execute on function public.falla(text, text), public.empresa(text), public.manual(uuid, date, jsonb),\n  public.chk(uuid, int, text), public.saldo(uuid, int, text), public.resp(text) to authenticated;\n\nset role authenticated;\nselect set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-0000000000a1', false) \\gset\n\n-- ---------- Glosario, fuente, cuentas controladas y catálogo ----------\ndo $$\nbegin\n  assert (select count(*) from erp.concepts where key in ('taxableBase', 'temporaryDifference', 'currentTax', 'deferredTax')) = 4, 'glosario';\n  assert (select ref from erp.sources where key = 'lis') like '%26 (bases negativas)%', 'fuente: Ley 27/2014 con sus artículos';\n  assert (select modules from erp.control_rules where account_prefix = '630') = '{corporate_tax}'\n     and (select modules from erp.control_rules where account_prefix = '474') = '{corporate_tax}', 'cuentas controladas 630 y 474';\n  assert not exists (select 1 from erp.control_rules where account_prefix in ('4752', '473', '4709')), 'el pago a Hacienda es manual';\n  assert (select screen from erp.operations where key = 'corporate_tax') = 'corporate_tax', 'catálogo de operaciones';\n  raise notice 'OK  · glosario (4 términos), fuente LIS, cuentas controladas 630 y 474, operación del catálogo';\nend $$;\n\n-- ---------- Supuestos de Practicar ----------\ndo $$\ndeclare g jsonb;\nbegin\n  g := erp.grade_exercise('corporate_tax_current', public.resp('6300 D 25000 | 473 H 8000 | 4752 H 17000'));\n  assert (g->>'ok')::boolean and (g->>'score')::int = 100, g::text;\n  g := erp.grade_exercise('corporate_tax_current', public.resp('6300 D 25000 | 473 H 8000 | 4750 H 17000'));\n  assert not (g->>'ok')::boolean and exists (select 1 from jsonb_array_elements(g->'tips') t where t->>'msg' like 'La 4750 es la deuda del IVA%'), g::text;\n  g := erp.grade_exercise('corporate_tax_deferred', public.resp('4740 D 650 | 6301 H 650'));\n  assert (g->>'ok')::boolean and (g->>'score')::int = 100, g::text;\n  g := erp.grade_exercise('corporate_tax_deferred', public.resp('6301 D 650 | 479 H 650'));\n  assert not (g->>'ok')::boolean and exists (select 1 from jsonb_array_elements(g->'tips') t where t->>'msg' like 'Pagas más impuesto ahora%'), g::text;\n  raise notice 'OK  · Practicar: impuesto corriente (6300 / 473 · 4752) y diferido (4740 / 6301), con sus errores típicos';\nend $$;\n\n-- ---------- Cierre, invariante y la 129 ----------\ndo $$\ndeclare e uuid := public.empresa('Cierre IS SL'); s uuid := public.empresa('Estricta SL'); z uuid := public.empresa('Sin actividad SL');\n        p jsonb; v_ret uuid;\nbegin\n  perform erp.set_control_mode(s, 'strict');\n  foreach v_ret in array array[e, s] loop\n    perform public.manual(v_ret, '2026-06-30', '[[\"57200001\", 50000, 0], [\"70500001\", 0, 50000]]');\n    perform public.manual(v_ret, '2026-07-31', '[[\"62900001\", 10000, 0], [\"57200001\", 0, 10000]]');\n    perform public.manual(v_ret, '2026-10-20', '[[\"47300001\", 3000, 0], [\"57200001\", 0, 3000]]');\n  end loop;\n  -- sin el impuesto: aviso en guiado, error en estricto; el asistente lo deja pendiente\n  assert public.chk(e, 2026, 'corporate_tax_missing') = 'warning', 'guiado: aviso';\n  assert public.chk(s, 2026, 'corporate_tax_missing') = 'error' and not (erp.year_closing_preview(s, 2026)->>'can_close')::boolean, 'estricto: no se cierra';\n  assert public.falla(format('select erp.close_fiscal_year(%L, 2026, true)', s), 'cannot be closed'), 'estricto: ni aceptando avisos';\n  assert (select status from erp.closing_checklist(e, 2026) where code = 'corporate_tax') = 'pending'\n     and (select step from erp.closing_checklist(e, 2026) where code = 'corporate_tax') = 10\n     and (select step from erp.closing_checklist(e, 2026) where code = 'close') = 11, 'asistente: paso 10 pendiente; el cierre es el 11';\n  assert (select status from erp.closing_checklist(z, 2026) where code = 'corporate_tax') = 'na' and public.chk(z, 2026, 'corporate_tax_missing') is null,\n         'sin resultado no hace falta';\n  assert (select status from erp.integrity_checks(e, 2026) where code = 'corporate_tax') = 'n/a';\n  -- en estricto, un asiento manual a la 630 no se contabiliza\n  assert public.falla(format('select public.manual(%L, %L, %L)', s, '2026-12-31', '[[\"63000001\", 100, 0], [\"57200001\", 0, 100]]'), 'controlled'),\n         'estricto: la 630 es del Impuesto sobre Sociedades';\n  raise notice 'OK  · sin el impuesto: aviso en guiado, error en estricto; asistente paso 10 pendiente (na sin resultado)';\n\n  -- se contabiliza: desaparece el aviso, el paso queda hecho y el invariante cuadra\n  perform erp.corporate_tax_settings(erp.corporate_tax_prepare(e, 2026), 'general', false);\n  perform erp.corporate_tax_post(e, 2026);\n  assert public.chk(e, 2026, 'corporate_tax_missing') is null and public.chk(e, 2026, 'withholdings_left') is null, 'ya no avisa';\n  assert (select status from erp.closing_checklist(e, 2026) where code = 'corporate_tax') = 'done';\n  assert (select status from erp.integrity_checks(e, 2026) where code = 'corporate_tax') = 'ok';\n  perform erp.corporate_tax_settings(erp.corporate_tax_prepare(s, 2026), 'general', false);\n  perform erp.corporate_tax_post(s, 2026);\n  execute 'set constraints all immediate';   -- el impuesto sí puede mover la 630 y la 474 en estricto\n  execute 'set constraints all deferred';\n  assert public.chk(s, 2026, 'corporate_tax_missing') is null and (erp.year_closing_preview(s, 2026)->>'can_close')::boolean, 'estricto: ya se puede cerrar';\n\n  -- un pago a cuenta registrado después: la 473 no queda a cero (aviso) y el invariante sigue cuadrando\n  perform public.manual(e, '2026-12-30', '[[\"47300001\", 500, 0], [\"57200001\", 0, 500]]');\n  assert public.chk(e, 2026, 'withholdings_left') = 'warning', 'la 473 no ha quedado a cero';\n  perform public.manual(e, '2026-12-30', '[[\"57200001\", 500, 0], [\"47300001\", 0, 500]]');\n  -- un asiento manual a la 630 (guiado lo deja) rompe el invariante\n  perform public.manual(e, '2026-12-31', '[[\"63000001\", 100, 0], [\"57200001\", 0, 100]]');\n  assert (select status from erp.integrity_checks(e, 2026) where code = 'corporate_tax') = 'fail', 'manual a la 630: no cuadra';\n  perform public.manual(e, '2026-12-31', '[[\"57200001\", 100, 0], [\"63000001\", 0, 100]]');\n  assert (select status from erp.integrity_checks(e, 2026) where code = 'corporate_tax') = 'ok';\n  raise notice 'OK  · contabilizado: paso hecho, invariante ok; aviso si la 473 no queda a cero; un manual a la 630 lo rompe';\n\n  -- la 129 = resultado antes de impuestos − gasto por impuesto\n  perform erp.close_fiscal_year(e, 2026, true);\n  assert public.saldo(e, 2026, '129') = 30000, 'la 129: ' || public.saldo(e, 2026, '129');\n  assert public.saldo(e, 2026, '4752') = 7000;\n  assert not exists (select 1 from erp.integrity_checks(e, 2026) where status = 'fail'),\n         (select string_agg(code, ', ') from erp.integrity_checks(e, 2026) where status = 'fail');\n  raise notice 'OK  · cerrado: la 129 = 40.000 − 10.000 = 30.000; 4752 7.000; todos los invariantes cuadran';\nend $$;\n\n-- ---------- Conceptos de los ajustes sin importes ----------\ndo $$\ndeclare e uuid := public.empresa('Conceptos SL');\nbegin\n  perform public.manual(e, '2026-06-30', '[[\"57200001\", 50000, 0], [\"70500001\", 0, 50000]]');\n  perform erp.create_fixed_asset(jsonb_build_object('company_id', e, 'name', 'Máquina',\n    'asset_account_no', '21300001', 'cost', 20000, 'start_date', '2026-01-01', 'useful_life_months', 48, 'class_code', 'MAQUINARIA'));\n  perform erp.post_depreciation(e, '2026-12-31');\n  perform erp.corporate_tax_prepare(e, 2026);\n  assert exists (select 1 from erp.corporate_tax_adjustments where company_id = e and origin = 'depreciation'), 'propone el ajuste';\n  assert not exists (select 1 from erp.corporate_tax_adjustments where company_id = e and concept ~ '\\d\\.\\d\\d'),\n         (select string_agg(concept, ' / ') from erp.corporate_tax_adjustments where company_id = e);\n  assert (select concept from erp.corporate_tax_adjustments where company_id = e and origin = 'depreciation') like '%máximo de la tabla: 12 \\%%',\n         (select concept from erp.corporate_tax_adjustments where company_id = e and origin = 'depreciation');\n  raise notice 'OK  · el concepto de los ajustes ya no lleva importes (van en su columna)';\nend $$;\n",
  "database/tests/test_fase12_closing.sql": "-- =====================================================================\n-- PRUEBAS FASE 12 · Cierre del ejercicio (migración 0017)\n-- =====================================================================\n\\set ON_ERROR_STOP 1\n\\set QUIET 1\n\ninsert into auth.users (id, email) values\n  ('00000000-0000-0000-0000-0000000000a1', 'admin@test.local'),\n  ('00000000-0000-0000-0000-0000000000b2', 'contable@test.local');\ninsert into erp.app_profiles (user_id, app_role, max_companies) values ('00000000-0000-0000-0000-0000000000a1', 'owner', null);\n\ncreate or replace function public.asiento(e uuid, d date, txt text, l jsonb, borrador boolean default false)\nreturns uuid language plpgsql as $$\ndeclare a uuid;\nbegin\n  insert into erp.journal_entries (company_id, fiscal_year_id, posting_date, description)\n  values (e, (select id from erp.fiscal_years where company_id = e and d between starting_date and ending_date), d, txt)\n  returning id into a;\n  insert into erp.journal_lines (entry_id, line_no, gl_account_id, debit, credit)\n  select a, x.ord, (select id from erp.gl_accounts where company_id = e and account_no = x.v->>0), (x.v->>1)::numeric, (x.v->>2)::numeric\n  from jsonb_array_elements(l) with ordinality as x(v, ord);\n  if not borrador then perform erp.post_entry(a); end if;\n  return a;\nend $$;\ngrant execute on function public.asiento(uuid, date, text, jsonb, boolean) to authenticated;\n\ncreate or replace function public.partida(e uuid, y int, st text, c text) returns numeric language sql as $$\n  select amount from erp.financial_statement(e, y, st) where code = c;\n$$;\ncreate or replace function public.saldo(e uuid, y int, cuenta text) returns numeric language sql as $$\n  select coalesce(sum(b.balance), 0) from erp.year_account_balances(\n    (select id from erp.fiscal_years where company_id = e and year = y)) b where b.account_no = cuenta;\n$$;\ngrant execute on function public.partida(uuid, int, text, text), public.saldo(uuid, int, text) to authenticated;\n\nset role authenticated;\nselect set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-0000000000a1', false) \\gset\n\ndo $$\ndeclare\n  e uuid; d uuid; c jsonb; r record; n int; ok boolean;\n  act_antes numeric; res_antes numeric;\nbegin\n  insert into erp.companies (name, industry, tax_territory, created_by)\n  values ('Cierre SL', 'retail', 'canary_islands', auth.uid()) returning id into e;\n  perform erp.create_fiscal_year(e, 2026);\n  perform erp.create_posting_account(e, s.no, s.name) from (values\n    ('10000001','Capital'), ('17000001','Préstamo'), ('21600001','Mobiliario'), ('28160001','A.A. mobiliario'),\n    ('40000001','Proveedor A'), ('43000001','Cliente A'), ('57000001','Caja'), ('57200001','Banco'),\n    ('60000001','Compras'), ('62100001','Alquiler'), ('68100001','Amortización'), ('70000001','Ventas'),\n    ('76900001','Otros ingresos financieros')) as s(no, name);\n  insert into erp.company_users (company_id, user_id, role) values (e, '00000000-0000-0000-0000-0000000000b2', 'accountant');\n\n  perform public.asiento(e, '2026-01-02', 'Constitución', '[[\"57200001\",10000,0],[\"10000001\",0,10000]]');\n  perform public.asiento(e, '2026-01-10', 'Préstamo', '[[\"57200001\",5000,0],[\"17000001\",0,5000]]');\n  perform public.asiento(e, '2026-01-15', 'Mobiliario', '[[\"21600001\",3000,0],[\"57200001\",0,3000]]');\n  perform public.asiento(e, '2026-02-01', 'Compra', '[[\"60000001\",4000,0],[\"40000001\",0,4000]]');\n  perform public.asiento(e, '2026-03-01', 'Venta', '[[\"43000001\",9000,0],[\"70000001\",0,9000]]');\n  perform public.asiento(e, '2026-03-05', 'Caja', '[[\"57000001\",500,0],[\"57200001\",0,500]]');\n  perform public.asiento(e, '2026-03-20', 'Alquiler', '[[\"62100001\",1200,0],[\"57200001\",0,1200]]');\n  perform public.asiento(e, '2026-06-30', 'Intereses cobrados', '[[\"57200001\",20,0],[\"76900001\",0,20]]');\n  perform public.asiento(e, '2026-12-31', 'Amortización', '[[\"68100001\",300,0],[\"28160001\",0,300]]');\n  -- Resultado: 9.000 + 20 − 4.000 − 1.200 − 300 = 3.520 de beneficio\n  act_antes := public.partida(e, 2026, 'balance', 'ACT');\n  res_antes := public.partida(e, 2026, 'pyg', 'PD');\n  assert res_antes = 3520, 'resultado antes del cierre';\n\n  -- ---------- 1) Comprobaciones ----------\n  c := erp.year_closing_preview(e, 2026);\n  -- (v0.41.0: el único aviso es que falta el Impuesto sobre Sociedades, que este supuesto no calcula)\n  assert (c->>'can_close')::boolean and (select jsonb_agg(x->>'code') from jsonb_array_elements(c->'checks') x where x->>'severity' <> 'info') = '[\"corporate_tax_missing\"]', 'sin errores ni más avisos: ' || (c->'checks')::text;\n  assert (c->>'result')::numeric = 3520;\n  assert c->>'result_account_no' = '12900000', '129 + ceros hasta 8 dígitos';\n  assert c->'checks' @> '[{\"code\":\"result_account_created\"},{\"code\":\"next_year_created\"}]', 'informa de lo que creará';\n  assert jsonb_array_length(c->'closing_pl_lines') = 6, '5 cuentas de gastos e ingresos + 129';\n  raise notice 'OK  · borrador: resultado 3.520, se crearán la 12900000 y el ejercicio 2027';\n\n  d := public.asiento(e, '2026-12-31', 'Borrador olvidado', '[[\"62100001\",10,0],[\"57000001\",0,10]]', true);\n  c := erp.year_closing_preview(e, 2026);\n  assert not (c->>'can_close')::boolean and c->'checks' @> '[{\"code\":\"draft_entries\",\"severity\":\"error\"}]';\n  begin\n    perform erp.close_fiscal_year(e, 2026, true); ok := false;\n  exception when others then ok := sqlerrm like '%draft_entries%';\n  end;\n  assert ok, 'con borradores no se cierra';\n  delete from erp.journal_entries where id = d;\n  raise notice 'OK  · un borrador impide el cierre';\n\n  perform erp.setup_taxes(e);   -- IGIC configurado y sin liquidar ningún trimestre → aviso\n  c := erp.year_closing_preview(e, 2026);\n  assert c->'checks' @> '[{\"code\":\"unsettled_quarters\",\"severity\":\"warning\",\"detail\":\"IGIC 1T, IGIC 2T, IGIC 3T, IGIC 4T\"}]';\n  begin\n    perform erp.close_fiscal_year(e, 2026); ok := false;\n  exception when others then ok := sqlerrm like '%accept the warnings%';\n  end;\n  assert ok, 'los avisos hay que aceptarlos';\n  raise notice 'OK  · trimestres sin liquidar: aviso que hay que aceptar';\n\n  -- Un contable (no admin) no puede cerrar\n  perform set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-0000000000b2', true);\n  begin\n    perform erp.close_fiscal_year(e, 2026, true); ok := false;\n  exception when others then ok := sqlerrm like '%Only the company admin%';\n  end;\n  assert ok, 'solo el admin cierra';\n  perform set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-0000000000a1', true);\n  raise notice 'OK  · solo el administrador cierra el ejercicio';\n\n  -- ---------- 2-4) Cerrar ----------\n  select * into r from erp.close_fiscal_year(e, 2026, true);\n  assert r.result = 3520 and r.closing_pl_no = 10 and r.closing_no = 11 and r.opening_no = 1, 'nº de asientos';\n  assert (select status from erp.fiscal_years where company_id = e and year = 2026) = 'closed';\n  assert (select status from erp.fiscal_years where company_id = e and year = 2027) = 'open', '2027 creado';\n  assert not exists (select 1 from erp.year_account_balances((select id from erp.fiscal_years where company_id = e and year = 2026))),\n    'tras el cierre todas las cuentas de 2026 están a cero';\n  assert public.saldo(e, 2027, '12900000') = -3520, 'la 129 abre con el beneficio (acreedora)';\n  assert public.saldo(e, 2027, '57200001') = 10320 and public.saldo(e, 2027, '28160001') = -300, 'apertura = saldos de cierre';\n  assert public.saldo(e, 2027, '70000001') = 0, 'los ingresos no pasan de año';\n  raise notice 'OK  · regularización (nº 10), cierre (nº 11) y apertura de 2027 (nº 1): 129 abre con 3.520 de beneficio';\n\n  -- Los informes se ven igual antes y después del cierre\n  assert public.partida(e, 2026, 'pyg', 'PD') = res_antes, 'PyG de 2026 intacta';\n  assert public.partida(e, 2026, 'balance', 'ACT') = act_antes, 'balance de 2026 intacto';\n  assert public.partida(e, 2026, 'balance', 'PN.A1.VII') = 3520;\n  assert public.partida(e, 2027, 'balance', 'ACT') = act_antes and public.partida(e, 2027, 'balance', 'PNP') = act_antes,\n    'el balance de 2027 arranca con el de 2026';\n  assert public.partida(e, 2027, 'balance', 'PN.A1.VII') = 3520, '129 pendiente de aplicar';\n  assert public.partida(e, 2027, 'pyg', 'PD') = 0;\n  assert (select amount_prev from erp.financial_statement(e, 2027, 'balance') where code = 'ACT') = act_antes, 'columna 2026';\n  raise notice 'OK  · balance y PyG de 2026 iguales tras cerrar; 2027 arranca con el balance de cierre';\n\n  -- ---------- Bloqueos ----------\n  begin\n    perform public.asiento(e, '2026-12-31', 'Ajuste tardío', '[[\"62100001\",100,0],[\"57200001\",0,100]]'); ok := false;\n  exception when others then ok := sqlerrm like '%is closed%';\n  end;\n  assert ok, 'ejercicio cerrado: no admite asientos';\n  begin\n    perform erp.reverse_entry((select closing_entry_id from erp.year_closings where company_id = e)); ok := false;\n  exception when others then ok := sqlerrm like '%reopen the fiscal year%';\n  end;\n  assert ok, 'los asientos del cierre no se anulan desde el diario';\n  begin\n    update erp.fiscal_years set status = 'open' where company_id = e and year = 2026; ok := false;\n  exception when others then ok := sqlerrm like '%Use the year-end closing%';\n  end;\n  assert ok, 'no se reabre cambiando el estado a mano';\n  begin\n    perform erp.post_closing_entry(e, (select id from erp.fiscal_years where company_id = e and year = 2027),\n      '2027-01-01', 'opening', 'x', 'x', '[]'); ok := false;\n  exception when others then ok := sqlerrm like '%only with close_fiscal_year%';\n  end;\n  assert ok, 'no se fabrican asientos de cierre fuera del asistente';\n  assert (select count(distinct entry_no) from erp.v_general_journal where company_id = e and source = 'closing') = 3;\n  raise notice 'OK  · bloqueos: sin asientos en 2026, sin anular el cierre desde el diario, sin cambiar el estado a mano';\n\n  -- El asiento de apertura no es movimiento de IGIC del 1T de 2027\n  assert erp.is_settlement_entry((select opening_entry_id from erp.year_closings where company_id = e));\n\n  -- ---------- Reabrir para un ajuste tardío ----------\n  perform public.asiento(e, '2027-01-20', 'Cobro cliente', '[[\"57200001\",9000,0],[\"43000001\",0,9000]]');\n  perform erp.reopen_fiscal_year(e, 2026);\n  assert (select status from erp.fiscal_years where company_id = e and year = 2026) = 'open';\n  assert public.saldo(e, 2026, '70000001') = -9000, 'vuelven los saldos de ingresos';\n  assert public.saldo(e, 2027, '12900000') = 0 and public.saldo(e, 2027, '57200001') = 9000, 'apertura anulada; queda el cobro';\n  assert (select count(*) from erp.journal_entries where company_id = e and reversal_of is not null) = 3, '3 contraasientos';\n  raise notice 'OK  · reabrir: 3 contraasientos (traza para el auditor) y 2026 vuelve a estar abierto';\n\n  perform public.asiento(e, '2026-12-31', 'Ajuste tardío', '[[\"62100001\",100,0],[\"57200001\",0,100]]');\n  select * into r from erp.close_fiscal_year(e, 2026, true);\n  assert r.result = 3420, 'nuevo resultado';\n  assert public.saldo(e, 2027, '12900000') = -3420 and public.saldo(e, 2027, '57200001') = 10220 + 9000;\n  assert (select count(*) from erp.v_year_closings where company_id = e) = 2\n     and (select count(*) from erp.v_year_closings where company_id = e and status = 'posted') = 1, 'historial';\n  raise notice 'OK  · ajuste y nuevo cierre: resultado 3.420';\n\n  -- ---------- Orden de los ejercicios ----------\n  select * into r from erp.close_fiscal_year(e, 2027, true);\n  begin\n    perform erp.reopen_fiscal_year(e, 2026); ok := false;\n  exception when others then ok := sqlerrm like '%Reopen fiscal year 2027 first%';\n  end;\n  assert ok, 'se reabre del más reciente al más antiguo';\n  perform erp.reopen_fiscal_year(e, 2027);\n  perform erp.reopen_fiscal_year(e, 2026);\n  c := erp.year_closing_preview(e, 2027);\n  assert c->'checks' @> '[{\"code\":\"previous_year_open\",\"severity\":\"error\"}]', 'no se cierra 2027 con 2026 abierto';\n  raise notice 'OK  · orden: se cierra del más antiguo al más reciente y se reabre al revés';\nend $$;\n\nreset role;\ndrop function public.asiento(uuid, date, text, jsonb, boolean);\ndrop function public.partida(uuid, int, text, text);\ndrop function public.saldo(uuid, int, text);\n\\echo '=========== TODAS LAS PRUEBAS DE LA FASE 12 (CIERRE DEL EJERCICIO) PASARON ==========='\n",
  "database/tests/test_fase32_concepts.sql": "-- =====================================================================\n-- PRUEBAS FASE 32 · Conceptos: el glosario en la base de datos (migración 0038)\n-- =====================================================================\n\\set ON_ERROR_STOP 1\n\\set QUIET 1\n\ninsert into auth.users (id, email) values ('00000000-0000-0000-0000-0000000000a1', 'usuario@test.local');\n\n-- Sin sesión (anon) no se ve: el glosario público lo da la web desde su propio fichero\nset role anon;\ndo $$\nbegin\n  perform 1 from erp.concepts;\n  raise exception 'anon no debería leer erp.concepts';\nexception when insufficient_privilege then\n  raise notice 'OK  · sin sesión no se lee (la web lleva su copia)';\nend $$;\nreset role;\n\nset role authenticated;\nselect set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-0000000000a1', false) \\gset\ndo $$\ndeclare v text;\nbegin\n  assert (select count(*) from erp.concepts) = 58, 'los 58 términos del glosario (41 + 2 del inmovilizado, 0042, + 2 de los ajustes de cierre, 0044, + 3 del cierre II, 0048, + 2 de nóminas, 0050, + 2 de modelos, 0053, + 2 de practicar, 0055, + 4 del Impuesto sobre Sociedades, 0059): ' || (select count(*) from erp.concepts);\n  assert (select term from erp.concepts where key = 'controlledAccount') = 'Cuenta controlada';\n  assert (select sap from erp.concepts where key = 'controlledAccount') = 'Reconciliation account';\n  assert (select pgc from erp.concepts where key = 'inputTax') = '{472}';\n  assert (select example from erp.concepts where key = 'doubleEntry') is null, 'sin ejemplo: null';\n  raise notice 'OK  · 48 conceptos con su definición, BC, SAP y cuentas del PGC';\n\n  -- Conceptos de una subcuenta\n  select string_agg(key, ',' order by key) into v from erp.concepts_for_account('41000001');\n  assert v = 'aging,controlledAccount,openItem,partner,thirdPartyReturn', v;\n  assert (select key from erp.concepts_for_account('47500001') limit 1) = 'settlement', 'la 4750 gana a la 47x';\n  assert (select count(*) from erp.concepts_for_account('62300001')) = 0, 'la 623 no tiene concepto (todavía)';\n  raise notice 'OK  · la 41000001 → tercero, partida abierta, antigüedad y cuenta controlada';\n\n  -- Cada comprobación del auditor, con su concepto\n  assert not exists (select 1 from erp.audit_checks where concept is null), 'todas con concepto';\n  assert (select c.term from erp.audit_checks a join erp.concepts c on c.key = a.concept where a.code = 'vat_input')\n         = 'IVA / IGIC soportado (472)';\n  raise notice 'OK  · cada comprobación enlaza con su concepto (472 → IVA / IGIC soportado)';\n\n  -- Nadie lo modifica desde la web\n  begin\n    update erp.concepts set term = 'X' where key = 'debit';\n    assert not found, 'sin permiso de escritura';\n  exception when insufficient_privilege then null;\n  end;\n  assert (select term from erp.concepts where key = 'debit') = 'Debe';\n  raise notice 'OK  · solo lectura';\nend $$;\n\n\\echo '✔ FASE 32 OK · conceptos'\n",
  "database/tests/test_fase38_year_end_adjustments.sql": "-- =====================================================================\n-- PRUEBAS FASE 38 · Fin de ejercicio I: periodificaciones y deterioro de clientes (migración 0043)\n-- ---------------------------------------------------------------------\n-- SUPUESTO DE REFERENCIA (calculado a mano desde la norma: PGC 2007, marco conceptual, principio de devengo;\n-- NRV 9.ª 2.1.3, deterioro de créditos; Ley 27/2014 del IS, arts. 13.1 y 104):\n--  Comercial Atlántico SL (Península), ejercicios 2026 y 2027.\n--  PERIODIFICACIONES al 31/12/2026\n--   A) Seguro anual del local pagado el 01/10/2026: 1.200 (625; exento de IVA, art. 20.Uno.16.º LIVA).\n--      Cubre 12 meses; de 2026 son 3 (300). Gasto anticipado 9/12 = 900:      480 D 900  / 625 H 900\n--   B) Alquiler de un local cobrado por adelantado el 01/11/2026: semestre 6.000 + IVA (752).\n--      De 2026 son 2 meses (2.000). Ingreso anticipado 4/6 = 4.000:           752 D 4.000 / 485 H 4.000\n--   C) Luz de diciembre, sin factura al cierre: estimación 350:               628 D 350  / 4009 H 350\n--   D) Mantenimiento de nov-dic-ene que se facturará el 31/01/2027 por 900:\n--      devengados 2 de 3 meses = 600:                                          4309 D 600 / 705 H 600\n--   Reversión el 01/01/2027 (asientos al revés): el gasto o el ingreso anticipado pasa al año en que se devenga; en\n--   los devengados (C, D), la reversión deja la 628 y la 705 en negativo, y la factura que llega en 2027 por el total\n--   las compensa (en 2027 solo queda lo que es de 2027).\n--   Efecto en el resultado de 2026: −300 (seguro) + 2.000 (alquiler) − 350 (luz) + 600 (mantenimiento).\n--  DETERIORO DE CLIENTES al 31/12/2026\n--   E) Moroso: factura del 15/03/2026 por 2.000 + IVA = 2.420, vencida el mismo día y sin cobrar. Individual al 100 %:\n--      694 D 2.420 / 490 H 2.420. Han pasado más de 6 meses del vencimiento: deducible (art. 13.1.a LIS).\n--   F) Dudoso: factura del 01/10/2026 por 1.000 + IVA = 1.210, cobra 410 el 15/11 → pendiente 800. Individual al 50 %:\n--      694 D 400 / 490 H 400. Vencida hace menos de 6 meses: NO deducible hasta el 01/04/2027.\n--   G) Global por antigüedad sobre el resto de clientes (no vencido 0 %, 1-90 días 5 %, 91-180 10 %, 181-365 25 %):\n--      Cliente General, con 30 días de pago:\n--        · 10/04/2026: 500 + IVA = 605, vence el 10/05 → 235 días → 25 % = 151,25\n--        · 15/06/2026: 1.000 + IVA = 1.210, vence el 15/07 → 169 días → 10 % = 121,00\n--        · 20/12/2026: 3.000 + IVA = 3.630, vence el 19/01/2027 → no vencida → 0\n--      Deterioro global 272,25 (694 / 490). No deducible (art. 13.1 LIS); una empresa de reducida dimensión podría\n--      deducir hasta el 1 % de los deudores: 1 % de 5.445 = 54,45 (art. 104 LIS).\n--  2027\n--   H) 15/02: Dudoso paga los 800 → se revierte su deterioro: 490 D 400 / 794 H 400\n--   I) 10/03: Moroso, insolvencia firme (concurso sin bienes): 650 D 2.420 / 430 H 2.420 · 490 D 2.420 / 794 H 2.420\n--      La partida abierta del Moroso queda a cero (como un cobro sin banco).\n-- =====================================================================\n\\set ON_ERROR_STOP 1\n\\set QUIET 1\n\ninsert into auth.users (id, email) values\n  ('00000000-0000-0000-0000-0000000000a1', 'admin@test.local'),\n  ('00000000-0000-0000-0000-0000000000b2', 'lector@test.local');\ninsert into erp.app_profiles (user_id, app_role, max_companies) values ('00000000-0000-0000-0000-0000000000a1', 'owner', null);\n\ncreate or replace function public.falla(sql text, texto text) returns boolean language plpgsql as $$\nbegin\n  execute sql;\n  return false;\nexception when others then\n  if sqlerrm ilike '%' || texto || '%' then return true; end if;\n  raise notice 'error inesperado: %', sqlerrm;\n  return false;\nend $$;\ncreate or replace function public.factura(e uuid, tipo text, tercero uuid, fecha date, lineas jsonb) returns uuid language sql as $$\n  select invoice_id from erp.post_invoice(jsonb_build_object('company_id', e, 'invoice_type', tipo, 'document_kind', 'invoice',\n    'partner_id', tercero, 'external_document_no', case tipo when 'purchase' then 'P-' || substr(md5(random()::text), 1, 8) end,\n    'invoice_date', fecha, 'description', 'Supuesto', 'lines', lineas));\n$$;\ncreate or replace function public.saldo(e uuid, y int, prefijo text) returns numeric language sql as $$\n  select coalesce(sum(debit_balance - credit_balance), 0) from erp.trial_balance(e, y) where account_no like prefijo || '%';\n$$;\n-- Saldo de las cuentas de un prefijo en el año, solo con los asientos normales (sin cierre ni apertura)\ncreate or replace function public.mov(e uuid, y int, prefijo text) returns numeric language sql as $$\n  select coalesce(sum(l.debit - l.credit), 0) from erp.journal_lines l join erp.journal_entries j on j.id = l.entry_id\n  join erp.fiscal_years fy on fy.id = j.fiscal_year_id and fy.year = y join erp.gl_accounts g on g.id = l.gl_account_id\n  where j.company_id = e and j.status = 'posted' and j.entry_type = 'normal' and g.account_no like prefijo || '%';\n$$;\ncreate or replace function public.asiento(e uuid, y int, n int) returns text language sql as $$\n  select string_agg(g.account_no || ' ' || case when l.debit > 0 then 'D ' || l.debit else 'H ' || l.credit end, ' | ' order by l.line_no)\n  from erp.journal_entries j join erp.fiscal_years fy on fy.id = j.fiscal_year_id and fy.year = y\n  join erp.journal_lines l on l.entry_id = j.id join erp.gl_accounts g on g.id = l.gl_account_id\n  where j.company_id = e and j.entry_no = n;\n$$;\ncreate or replace function public.pendiente(e uuid, f uuid, d date) returns numeric language sql as $$\n  select pending from erp.open_items(e, d) where invoice_id = f;\n$$;\ncreate or replace function public.comprueba() returns void language plpgsql as $$\nbegin execute 'set constraints all immediate'; execute 'set constraints all deferred'; end $$;\ngrant execute on function public.falla(text, text), public.factura(uuid, text, uuid, date, jsonb), public.saldo(uuid, int, text),\n  public.mov(uuid, int, text), public.asiento(uuid, int, int), public.pendiente(uuid, uuid, date), public.comprueba() to authenticated;\ncreate table public.ctx (k text primary key, v uuid);\ngrant all on public.ctx to authenticated;\n\nset role authenticated;\nselect set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-0000000000a1', false) \\gset\n\ndo $$\ndeclare\n  e uuid; aseg uuid; inq uuid; moroso uuid; dudoso uuid; general uuid;\n  fseg uuid; falq uuid; fmor uuid; fdud uuid; g1 uuid; g2 uuid; g3 uuid;\n  r record; s text; a_seg uuid; d_mor uuid; d_dud uuid; d_glo uuid; w uuid;\nbegin\n  insert into erp.companies (name, industry, tax_territory, created_by)\n  values ('Comercial Atlántico SL', 'retail', 'mainland', auth.uid()) returning id into e;\n  insert into public.ctx values ('empresa', e);\n  insert into erp.company_users (company_id, user_id, role) values (e, '00000000-0000-0000-0000-0000000000b2', 'viewer');\n  perform erp.create_fiscal_year(e, 2026);\n  perform erp.create_fiscal_year(e, 2027);\n  perform erp.setup_taxes(e);\n  perform erp.set_control_mode(e, 'strict');      -- los módulos funcionan en modo estricto\n  perform erp.create_posting_account(e, x.no, x.name) from (values\n    ('62500001', 'Seguro del local'), ('62800001', 'Electricidad'), ('75200001', 'Alquiler del local'),\n    ('70500001', 'Mantenimiento'), ('70000001', 'Ventas'), ('57200001', 'Banco')) as x(no, name);\n  select partner_id into aseg    from erp.create_partner(e, 'creditor', 'Seguros del Norte SA', 'B12345674');\n  select partner_id into inq     from erp.create_partner(e, 'customer', 'Inquilino Local SL', 'A58818501');\n  select partner_id into moroso  from erp.create_partner(e, 'customer', 'Moroso', '12345678Z');\n  select partner_id into dudoso  from erp.create_partner(e, 'customer', 'Dudoso', '87654321X');\n  select partner_id into general from erp.create_partner(e, 'customer', 'Cliente General SL', 'B11111119');\n  update erp.business_partners set payment_days = 30 where id = general;\n\n  -- ---------- 1. Periodificaciones al 31/12/2026 ----------\n  fseg := public.factura(e, 'purchase', aseg, '2026-10-01', '[{\"account_no\":\"62500001\",\"amount\":1200,\"tax_code\":\"VAT_E20\"}]');\n  select * into r from erp.create_accrual(jsonb_build_object('company_id', e, 'kind', 'prepaid_expense', 'description', 'Seguro anual del local',\n    'pl_account_no', '62500001', 'cutoff_date', '2026-12-31', 'total_amount', 1200, 'coverage_start', '2026-10-01',\n    'coverage_months', 12, 'invoice_id', fseg));\n  a_seg := r.accrual_id;\n  assert r.code = 'PER-0001' and r.amount = 900, 'seguro: 9/12 de 1.200 = 900: ' || row_to_json(r)::text;\n  assert public.asiento(e, 2026, r.entry_no) = '48000001 D 900.00 | 62500001 H 900.00', public.asiento(e, 2026, r.entry_no);\n\n  falq := public.factura(e, 'sale', inq, '2026-11-01', '[{\"account_no\":\"75200001\",\"amount\":6000,\"tax_code\":\"VAT21\"}]');\n  perform erp.post_payment(jsonb_build_object('company_id', e, 'payment_type', 'collection', 'partner_id', inq,\n    'payment_date', '2026-11-01', 'cash_account_no', '57200001', 'applications', jsonb_build_array(jsonb_build_object('invoice_id', falq, 'amount', 7260))));\n  select * into r from erp.create_accrual(jsonb_build_object('company_id', e, 'kind', 'deferred_income', 'description', 'Alquiler cobrado por adelantado',\n    'pl_account_no', '75200001', 'cutoff_date', '2026-12-31', 'total_amount', 6000, 'coverage_start', '2026-11-01', 'coverage_months', 6));\n  assert r.amount = 4000 and public.asiento(e, 2026, r.entry_no) = '75200001 D 4000.00 | 48500001 H 4000.00', 'alquiler: 4/6 de 6.000 = 4.000';\n\n  select * into r from erp.create_accrual(jsonb_build_object('company_id', e, 'kind', 'accrued_expense', 'description', 'Luz de diciembre',\n    'pl_account_no', '62800001', 'cutoff_date', '2026-12-31', 'amount', 350));\n  assert public.asiento(e, 2026, r.entry_no) = '62800001 D 350.00 | 40090001 H 350.00', public.asiento(e, 2026, r.entry_no);\n\n  select * into r from erp.create_accrual(jsonb_build_object('company_id', e, 'kind', 'accrued_income', 'description', 'Mantenimiento nov-ene',\n    'pl_account_no', '70500001', 'cutoff_date', '2026-12-31', 'total_amount', 900, 'coverage_start', '2026-11-01', 'coverage_months', 3));\n  assert r.amount = 600 and public.asiento(e, 2026, r.entry_no) = '43090001 D 600.00 | 70500001 H 600.00', 'mantenimiento: 2/3 de 900 = 600';\n\n  assert public.saldo(e, 2026, '625') = 300 and public.saldo(e, 2026, '752') = -2000\n     and public.saldo(e, 2026, '628') = 350 and public.saldo(e, 2026, '705') = -600, 'gastos e ingresos de 2026 por devengo';\n  assert public.saldo(e, 2026, '480') = 900 and public.saldo(e, 2026, '485') = -4000\n     and public.saldo(e, 2026, '4009') = -350 and public.saldo(e, 2026, '4309') = 600, 'cuentas de periodificación';\n  raise notice 'OK  · periodificaciones: 480 900 · 485 4.000 · 4009 350 · 4309 600; gasto del seguro 300 e ingreso del alquiler 2.000 en 2026';\n\n  -- …errores\n  assert public.falla(format('select * from erp.create_accrual(%L)', jsonb_build_object('company_id', e, 'kind', 'prepaid_expense',\n           'description', 'X', 'pl_account_no', '70500001', 'cutoff_date', '2026-12-31', 'amount', 10)), 'expense account'), 'gasto en el grupo 6';\n  assert public.falla(format('select * from erp.create_accrual(%L)', jsonb_build_object('company_id', e, 'kind', 'prepaid_expense',\n           'description', 'X', 'pl_account_no', '62500001', 'cutoff_date', '2026-12-31', 'total_amount', 1200,\n           'coverage_start', '2026-01-01', 'coverage_months', 12)), 'Nothing to accrue'), 'un periodo que acaba en el corte no se periodifica';\n  assert public.falla(format('select * from erp.create_accrual(%L)', jsonb_build_object('company_id', e, 'kind', 'otro',\n           'description', 'X', 'pl_account_no', '62500001', 'cutoff_date', '2026-12-31', 'amount', 10)), 'Invalid accrual type');\n  raise notice 'OK  · errores: cuenta del grupo equivocado, nada que periodificar y tipo desconocido';\n\n  -- …modo estricto: la 480 no se toca a mano; el asiento no se anula desde el diario\n  insert into erp.journal_entries (company_id, fiscal_year_id, posting_date, description)\n  values (e, (select id from erp.fiscal_years where company_id = e and year = 2026), '2026-12-31', 'A mano') returning id into w;\n  insert into erp.journal_lines (entry_id, company_id, line_no, gl_account_id, debit, credit) values\n    (w, e, 1, (select id from erp.gl_accounts where company_id = e and account_no = '48000001'), 10, 0),\n    (w, e, 2, (select id from erp.gl_accounts where company_id = e and account_no = '62500001'), 0, 10);\n  assert public.falla(format('select erp.post_entry(%L); select public.comprueba()', w), 'controlled by accruals'), 'estricto: 480 a mano no';\n  delete from erp.journal_lines where entry_id = w; delete from erp.journal_entries where id = w;\n  assert public.falla(format('select erp.reverse_entry(%L, %L, %L)', (select entry_id from erp.accruals where id = a_seg), '2026-12-31', 'x'),\n           'belongs to an accrual'), 'no se anula desde el diario';\n  raise notice 'OK  · modo estricto: la 480 solo la mueve el módulo; su asiento no se anula desde el diario';\n\n  -- ---------- 2. Deterioro individual ----------\n  fmor := public.factura(e, 'sale', moroso, '2026-03-15', '[{\"account_no\":\"70000001\",\"amount\":2000,\"tax_code\":\"VAT21\"}]');\n  fdud := public.factura(e, 'sale', dudoso, '2026-10-01', '[{\"account_no\":\"70000001\",\"amount\":1000,\"tax_code\":\"VAT21\"}]');\n  perform erp.post_payment(jsonb_build_object('company_id', e, 'payment_type', 'collection', 'partner_id', dudoso,\n    'payment_date', '2026-11-15', 'cash_account_no', '57200001', 'applications', jsonb_build_array(jsonb_build_object('invoice_id', fdud, 'amount', 410))));\n  select * into r from erp.impair_receivable(jsonb_build_object('invoice_id', fmor, 'impair_date', '2026-12-31'));\n  d_mor := r.impairment_id;\n  assert r.code = 'DET-0001' and r.amount = 2420 and r.warnings = '[]', 'Moroso: 100 % de 2.420, deducible: ' || row_to_json(r)::text;\n  assert public.asiento(e, 2026, r.entry_no) = '69400001 D 2420.00 | 49000001 H 2420.00', public.asiento(e, 2026, r.entry_no);\n  select * into r from erp.impair_receivable(jsonb_build_object('invoice_id', fdud, 'impair_date', '2026-12-31', 'pct', 50));\n  d_dud := r.impairment_id;\n  assert r.amount = 400, 'Dudoso: 50 % de lo pendiente (800) = 400';\n  assert r.warnings->0->>'code' = 'not_deductible_6m' and r.warnings->0->>'deductible_from' = '2027-04-01', 'aviso fiscal: ' || r.warnings::text;\n  assert public.pendiente(e, fmor, '2026-12-31') = 2420, 'la deuda sigue en la 430: la partida abierta no cambia';\n  raise notice 'OK  · deterioro individual: Moroso 2.420 (deducible) y Dudoso 400 (no deducible hasta el 01/04/2027, art. 13.1.a LIS)';\n\n  assert public.falla(format('select * from erp.impair_receivable(%L)', jsonb_build_object('invoice_id', fmor, 'impair_date', '2026-12-31')),\n           'already impaired'), 'un deterioro activo por factura';\n  assert public.falla(format('select * from erp.impair_receivable(%L)', jsonb_build_object('invoice_id', falq, 'impair_date', '2026-12-31')),\n           'nothing pending'), 'una factura cobrada no se deteriora';\n  assert public.falla(format('select * from erp.impair_receivable(%L)', jsonb_build_object('invoice_id', fseg, 'impair_date', '2026-12-31')),\n           'Only issued invoices'), 'solo facturas emitidas';\n  assert public.falla(format('select * from erp.impair_receivable(%L)', jsonb_build_object('invoice_id', fmor, 'impair_date', '2026-12-31', 'pct', 120)),\n           'between 0 and 100');\n  raise notice 'OK  · errores: deterioro repetido, factura cobrada, factura recibida y porcentaje fuera de rango';\n\n  -- ---------- 3. Deterioro global por antigüedad ----------\n  g1 := public.factura(e, 'sale', general, '2026-04-10', '[{\"account_no\":\"70000001\",\"amount\":500,\"tax_code\":\"VAT21\"}]');\n  g2 := public.factura(e, 'sale', general, '2026-06-15', '[{\"account_no\":\"70000001\",\"amount\":1000,\"tax_code\":\"VAT21\"}]');\n  g3 := public.factura(e, 'sale', general, '2026-12-20', '[{\"account_no\":\"70000001\",\"amount\":3000,\"tax_code\":\"VAT21\"}]');\n  select string_agg(tier || ':' || basis || '×' || pct || '=' || amount, ' ' order by tier) into s\n  from erp.global_impairment_calc(e, '2026-12-31', '{\"not_due\":0,\"d1_90\":5,\"d91_180\":10,\"d181_365\":25}');\n  assert s = 'd181_365:605.00×25=151.25 d1_90:0×5=0.00 d365_plus:0×0=0.00 d91_180:1210.00×10=121.00 not_due:3630.00×0=0.00', s;\n  select * into r from erp.impair_receivables_global(jsonb_build_object('company_id', e, 'impair_date', '2026-12-31',\n    'rates', '{\"not_due\":0,\"d1_90\":5,\"d91_180\":10,\"d181_365\":25}'::jsonb));\n  d_glo := r.impairment_id;\n  assert r.amount = 272.25, 'global 151,25 + 121 = 272,25: ' || r.amount;\n  assert r.warnings->0->>'code' = 'global_not_deductible' and (r.warnings->0->>'erd_limit')::numeric = 54.45, 'ERD: 1 % de 5.445: ' || r.warnings::text;\n  assert public.falla(format('select * from erp.impair_receivables_global(%L)', jsonb_build_object('company_id', e, 'impair_date', '2026-12-31',\n           'rates', '{\"not_due\":1}'::jsonb)), 'already a global'), 'un global activo';\n  assert public.saldo(e, 2026, '694') = 2420 + 400 + 272.25 and public.saldo(e, 2026, '490') = -(2420 + 400 + 272.25), '694 y 490 = 3.092,25';\n  raise notice 'OK  · global: 25 %% de 605 + 10 %% de 1.210 = 272,25 (sin Moroso ni Dudoso); no deducible, tope ERD 54,45 (art. 104 LIS)';\n\n  -- ---------- 4. Cierre de 2026 y reversión en la apertura de 2027 ----------\n  perform erp.set_control_mode(e, 'guided');   -- v0.41.0: en estricto no se cierra sin el Impuesto sobre Sociedades (aquí no se calcula)\n  perform erp.close_fiscal_year(e, 2026, true);\n  perform erp.set_control_mode(e, 'strict');\n  assert erp.reverse_accruals(e, '2027-01-01') = 4, 'las cuatro';\n  assert public.saldo(e, 2027, '480') = 0 and public.saldo(e, 2027, '485') = 0\n     and public.saldo(e, 2027, '4009') = 0 and public.saldo(e, 2027, '4309') = 0, 'cuentas de periodificación a cero en 2027';\n  assert public.mov(e, 2027, '625') = 900 and public.mov(e, 2027, '752') = -4000\n     and public.mov(e, 2027, '628') = -350 and public.mov(e, 2027, '705') = 600,\n         'el seguro (900) y el alquiler (4.000) pasan a 2027; la luz y el mantenimiento, en negativo: los compensa la factura de 2027';\n  assert (select reversal_entry_no is not null and reversal_year = 2027 from erp.v_accruals where id = a_seg), 'la ficha enlaza la reversión';\n  assert public.falla(format('select erp.reverse_accrual(%L)', a_seg), 'not pending'), 'no se revierte dos veces';\n  raise notice 'OK  · cierre de 2026 y reversión el 01/01/2027: 480/485/4009/4309 a cero; 900 de seguro y 4.000 de alquiler en 2027';\n\n  -- …deshacer: primero la reversión, después la periodificación (y se vuelve a hacer)\n  perform erp.cancel_accrual(a_seg);\n  assert (select status from erp.accruals where id = a_seg) = 'active' and public.saldo(e, 2027, '480') = 900, 'reversión deshecha';\n  perform erp.reverse_accrual(a_seg, '2027-01-01');\n  assert public.saldo(e, 2027, '480') = 0;\n  raise notice 'OK  · la reversión se deshace y se vuelve a hacer';\n\n  -- ---------- 5. 2027: cobro del Dudoso y reversión de su deterioro ----------\n  perform erp.post_payment(jsonb_build_object('company_id', e, 'payment_type', 'collection', 'partner_id', dudoso,\n    'payment_date', '2027-02-15', 'cash_account_no', '57200001', 'applications', jsonb_build_array(jsonb_build_object('invoice_id', fdud, 'amount', 800))));\n  select erp.reverse_impairment(d_dud, '2027-02-15') into r;\n  assert public.asiento(e, 2027, (select end_entry_no from erp.v_receivable_impairments where id = d_dud))\n         = '49000001 D 400.00 | 79400001 H 400.00', 'reversión 490 / 794';\n  raise notice 'OK  · cobrado el Dudoso: se revierte su deterioro (490 D 400 / 794 H 400)';\n\n  -- ---------- 6. Insolvencia firme del Moroso ----------\n  select * into r from erp.write_off_receivable(jsonb_build_object('invoice_id', fmor, 'writeoff_date', '2027-03-10'));\n  w := r.writeoff_id;\n  assert r.amount = 2420 and r.impairment_applied = 2420, row_to_json(r)::text;\n  assert public.asiento(e, 2027, r.entry_no) = '65000001 D 2420.00 | 43000002 H 2420.00 | 49000001 D 2420.00 | 79400001 H 2420.00',\n         public.asiento(e, 2027, r.entry_no);   -- 43000002: la subcuenta del Moroso\n  assert public.pendiente(e, fmor, '2027-03-10') = 0, 'la partida abierta del Moroso queda a cero';\n  assert (select status from erp.receivable_impairments where id = d_mor) = 'written_off';\n  assert (select items from erp.run_audit_checks(e, 2027) where code = 'partners') = 0, 'terceros: pendiente = saldo';\n  raise notice 'OK  · insolvencia firme: 650 D 2.420 / 430 H 2.420 · 490 D 2.420 / 794 H 2.420; la partida abierta queda a cero';\n\n  -- …no se anula desde Cobros y pagos, sí desde el módulo\n  assert public.falla(format('select erp.cancel_payment(%L)', (select payment_id from erp.receivable_writeoffs where id = w)),\n           'receivable impairment'), 'no desde Cobros y pagos';\n  assert public.falla(format('select erp.cancel_impairment(%L)', d_mor), 'cancel the write-off first');\n  perform erp.cancel_write_off(w);\n  assert public.pendiente(e, fmor, '2027-03-10') = 2420 and (select status from erp.receivable_impairments where id = d_mor) = 'active', 'vuelve a estar pendiente y deteriorada';\n  select * into r from erp.write_off_receivable(jsonb_build_object('invoice_id', fmor, 'writeoff_date', '2027-03-10'));\n  raise notice 'OK  · la insolvencia no se anula desde Cobros y pagos; desde el módulo, sí (y la factura vuelve a deber)';\n\n  -- ---------- 7. El global se re-estima cada año: reversión y deshacer ----------\n  perform erp.reverse_impairment(d_glo, '2027-12-31');\n  assert public.falla(format('select erp.reverse_impairment(%L, %L)', d_glo, '2027-12-31'), 'not active');\n  perform erp.cancel_impairment(d_glo);\n  assert (select status from erp.receivable_impairments where id = d_glo) = 'active', 'reversión deshecha';\n  perform erp.reverse_impairment(d_glo, '2027-12-31');\n  assert public.saldo(e, 2027, '490') = 0, 'la 490 queda a cero en 2027: ' || public.saldo(e, 2027, '490');\n  assert public.mov(e, 2027, '794') = -(400 + 2420 + 272.25), '794 = 3.092,25';\n  raise notice 'OK  · el global se revierte al año siguiente; la 490 queda a cero (794 = 3.092,25)';\n\n  -- ---------- 8. Invariantes, diario y comprobaciones ----------\n  perform public.comprueba();\n  assert not exists (select 1 from erp.integrity_checks(e, 2026) where status = 'fail'),\n         '2026: ' || (select string_agg(code, ', ') from erp.integrity_checks(e, 2026) where status = 'fail');\n  assert not exists (select 1 from erp.integrity_checks(e, 2027) where status = 'fail'),\n         '2027: ' || (select string_agg(code, ', ') from erp.integrity_checks(e, 2027) where status = 'fail');\n  assert (select items from erp.run_audit_checks(e, 2027) where code = 'controlled') = 0, 'los asientos de los módulos no son manuales';\n  assert (select count(distinct entry_no) from erp.v_general_journal where company_id = e and fiscal_year = 2026 and source = 'accrual') = 4;\n  assert (select count(distinct entry_no) from erp.v_general_journal where company_id = e and fiscal_year = 2027 and source = 'impairment') >= 3;\n  raise notice 'OK  · invariantes en verde; el diario marca periodificaciones y deterioros, y no salen como manuales';\nend $$;\n\n-- ---------- 9. Seguridad ----------\nselect set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-0000000000b2', false) \\gset\ndo $$\ndeclare e uuid := (select v from public.ctx where k = 'empresa');\nbegin\n  assert (select count(*) from erp.v_accruals where company_id = e) = 4, 'el lector ve las periodificaciones';\n  assert (select count(*) from erp.v_receivable_impairments where company_id = e) = 3, 'y los deterioros';\n  assert public.falla(format('select * from erp.create_accrual(%L)', jsonb_build_object('company_id', e, 'kind', 'accrued_expense',\n           'description', 'X', 'pl_account_no', '62800001', 'cutoff_date', '2027-12-31', 'amount', 10)), 'No permission'), 'pero no periodifica';\n  assert public.falla(format('select erp.adjust_account(%L, %L, %L)', e, '480', 'X'), 'permission denied'), 'las ayudas no son públicas';\n  begin\n    insert into erp.accruals (company_id, code, kind, description, pl_account_id, balance_account_id, cutoff_date, amount, entry_id)\n    select e, 'X', 'accrued_expense', 'X', id, id, current_date, 1, (select id from erp.journal_entries where company_id = e limit 1)\n    from erp.gl_accounts where company_id = e limit 1;\n    raise exception 'no debería poder insertar';\n  exception when insufficient_privilege then null;\n  end;\n  raise notice 'OK  · el lector ve, no periodifica ni escribe en las tablas';\nend $$;\n\n-- ---------- 10. Borrar la empresa ----------\nselect set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-0000000000a1', false) \\gset\ndo $$\ndeclare e uuid := (select v from public.ctx where k = 'empresa'); n int;\nbegin\n  loop n := erp.delete_company_step(e, 5); exit when n = 0; end loop;\n  perform public.comprueba();\n  assert not exists (select 1 from erp.companies where id = e);\n  raise notice 'OK  · una empresa con periodificaciones, deterioros e insolvencias se borra entera';\nend $$;\n\n\\echo '✔ FASE 38 OK · periodificaciones y deterioro de clientes'\n",
  "database/tests/test_fase40_provisions.sql": "-- =====================================================================\n-- PRUEBAS FASE 40 · Provisiones (migración 0045) · con su SUPUESTO DE REFERENCIA\n-- ---------------------------------------------------------------------\n-- Supuesto (calculado a mano desde la norma: PGC 2007, NRV 15.ª y cuentas 141, 142, 499, 529, 695 y 795):\n--  Servicios Teide SL, ejercicios 2026 a 2028.\n--   A) LITIGIO. Un cliente demanda a la empresa en 2026; el abogado ve probable una condena de 12.000 que se resolverá\n--      en 2028 (más de un año: largo plazo).\n--        31/12/2026  dotación                678 D 12.000 / 142 H 12.000\n--        31/12/2027  nueva estimación 15.000  678 D 3.000  / 142 H 3.000\n--                    vence en menos de un año → reclasificación  142 D 15.000 / 5293 H 15.000\n--        15/03/2028  sentencia: paga 14.000   5293 D 15.000 / 572 H 14.000 · 7953 H 1.000 (exceso)\n--   B) GARANTÍAS (operaciones comerciales). Estimación del 2 % de las ventas con garantía (50.000) = 1.000.\n--        31/12/2026  6959 D 1.000 / 4999 H 1.000\n--        31/12/2027  nueva estimación 1.200: el PGC revierte la anterior y dota la nueva (no el neto):\n--                    4999 D 1.000 / 7954 H 1.000 · 6959 D 1.200 / 4999 H 1.200\n--   C) IMPUESTOS. Acta de inspección del Impuesto sobre Sociedades de 2024, que se pagará en 2027: 3.000 (corto plazo).\n--        31/12/2026  633 D 3.000 / 5292 H 3.000\n--        20/04/2027  paga 3.200: 5292 D 3.000 · 633 D 200 / 572 H 3.200 (lo pagado de más, al mismo gasto)\n-- =====================================================================\n\\set ON_ERROR_STOP 1\n\\set QUIET 1\n\ninsert into auth.users (id, email) values\n  ('00000000-0000-0000-0000-0000000000a1', 'admin@test.local'),\n  ('00000000-0000-0000-0000-0000000000b2', 'lector@test.local');\ninsert into erp.app_profiles (user_id, app_role, max_companies) values ('00000000-0000-0000-0000-0000000000a1', 'owner', null);\n\ncreate or replace function public.falla(sql text, texto text) returns boolean language plpgsql as $$\nbegin\n  execute sql;\n  return false;\nexception when others then\n  if sqlerrm ilike '%' || texto || '%' then return true; end if;\n  raise notice 'error inesperado: %', sqlerrm;\n  return false;\nend $$;\ncreate or replace function public.saldo(e uuid, y int, prefijo text) returns numeric language sql as $$\n  select coalesce(sum(debit_balance - credit_balance), 0) from erp.trial_balance(e, y) where account_no like prefijo || '%';\n$$;\ncreate or replace function public.mov(e uuid, y int, prefijo text) returns numeric language sql as $$\n  select coalesce(sum(l.debit - l.credit), 0) from erp.journal_lines l join erp.journal_entries j on j.id = l.entry_id\n  join erp.fiscal_years fy on fy.id = j.fiscal_year_id and fy.year = y join erp.gl_accounts g on g.id = l.gl_account_id\n  where j.company_id = e and j.status = 'posted' and j.entry_type = 'normal' and g.account_no like prefijo || '%';\n$$;\ncreate or replace function public.asiento(e uuid, y int, n int) returns text language sql as $$\n  select string_agg(g.account_no || ' ' || case when l.debit > 0 then 'D ' || l.debit else 'H ' || l.credit end, ' | ' order by l.line_no)\n  from erp.journal_entries j join erp.fiscal_years fy on fy.id = j.fiscal_year_id and fy.year = y\n  join erp.journal_lines l on l.entry_id = j.id join erp.gl_accounts g on g.id = l.gl_account_id\n  where j.company_id = e and j.entry_no = n;\n$$;\ncreate or replace function public.comprueba() returns void language plpgsql as $$\nbegin execute 'set constraints all immediate'; execute 'set constraints all deferred'; end $$;\ngrant execute on function public.falla(text, text), public.saldo(uuid, int, text), public.mov(uuid, int, text),\n  public.asiento(uuid, int, int), public.comprueba() to authenticated;\ncreate table public.ctx (k text primary key, v uuid);\ngrant all on public.ctx to authenticated;\n\nset role authenticated;\nselect set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-0000000000a1', false) \\gset\n\ndo $$\ndeclare e uuid; lit uuid; gar uuid; imp uuid; r record; n int; w uuid;\nbegin\n  insert into erp.companies (name, industry, tax_territory, created_by)\n  values ('Servicios Teide SL', 'services', 'canary_islands', auth.uid()) returning id into e;\n  insert into public.ctx values ('empresa', e);\n  insert into erp.company_users (company_id, user_id, role) values (e, '00000000-0000-0000-0000-0000000000b2', 'viewer');\n  perform erp.create_fiscal_year(e, 2026);\n  perform erp.create_fiscal_year(e, 2027);\n  perform erp.create_fiscal_year(e, 2028);\n  perform erp.setup_taxes(e);\n  perform erp.set_control_mode(e, 'strict');\n  perform erp.create_posting_account(e, x.no, x.name) from (values\n    ('67800001', 'Gastos excepcionales'), ('63300001', 'Ajustes negativos en la imposición sobre beneficios'),\n    ('57200001', 'Banco'), ('10000001', 'Capital')) as x(no, name);\n  -- capital para que el banco tenga saldo\n  insert into erp.journal_entries (company_id, fiscal_year_id, posting_date, description)\n  values (e, (select id from erp.fiscal_years where company_id = e and year = 2026), '2026-01-02', 'Capital') returning id into w;\n  insert into erp.journal_lines (entry_id, company_id, line_no, gl_account_id, debit, credit) values\n    (w, e, 1, (select id from erp.gl_accounts where company_id = e and account_no = '57200001'), 50000, 0),\n    (w, e, 2, (select id from erp.gl_accounts where company_id = e and account_no = '10000001'), 0, 50000);\n  perform erp.post_entry(w);\n\n  -- ---------- 1. Dotaciones al 31/12/2026 ----------\n  select * into r from erp.create_provision(jsonb_build_object('company_id', e, 'kind', 'liabilities', 'term', 'long',\n    'description', 'Demanda de un cliente', 'amount', 12000, 'provision_date', '2026-12-31', 'expense_account_no', '67800001'));\n  lit := r.provision_id;\n  assert r.code = 'PRV-0001' and public.asiento(e, 2026, r.entry_no) = '67800001 D 12000.00 | 14200001 H 12000.00', public.asiento(e, 2026, r.entry_no);\n  select * into r from erp.create_provision(jsonb_build_object('company_id', e, 'kind', 'commercial',\n    'description', 'Garantías de ventas (2 % de 50.000)', 'amount', 1000, 'provision_date', '2026-12-31'));\n  gar := r.provision_id;\n  assert public.asiento(e, 2026, r.entry_no) = '69590001 D 1000.00 | 49990001 H 1000.00', public.asiento(e, 2026, r.entry_no);\n  select * into r from erp.create_provision(jsonb_build_object('company_id', e, 'kind', 'taxes', 'term', 'short',\n    'description', 'Acta de inspección del IS 2024', 'amount', 3000, 'provision_date', '2026-12-31', 'expense_account_no', '63300001'));\n  imp := r.provision_id;\n  assert public.asiento(e, 2026, r.entry_no) = '63300001 D 3000.00 | 52920001 H 3000.00', public.asiento(e, 2026, r.entry_no);\n  assert public.saldo(e, 2026, '142') = -12000 and public.saldo(e, 2026, '4999') = -1000 and public.saldo(e, 2026, '5292') = -3000;\n  raise notice 'OK  · dotaciones 2026: 142 12.000 (678), 4999 1.000 (6959), 5292 3.000 (633)';\n\n  -- …errores\n  assert public.falla(format('select * from erp.create_provision(%L)', jsonb_build_object('company_id', e, 'kind', 'liabilities',\n           'description', 'X', 'amount', 10, 'provision_date', '2026-12-31', 'expense_account_no', '57200001')), 'expense account by nature');\n  assert public.falla(format('select * from erp.create_provision(%L)', jsonb_build_object('company_id', e, 'kind', 'otra',\n           'description', 'X', 'amount', 10, 'provision_date', '2026-12-31')), 'Invalid provision type');\n  assert public.falla(format('select * from erp.create_provision(%L)', jsonb_build_object('company_id', e, 'kind', 'taxes',\n           'description', 'X', 'amount', 0, 'provision_date', '2026-12-31', 'expense_account_no', '63300001')), 'greater than zero');\n  raise notice 'OK  · errores: gasto que no es por naturaleza, tipo desconocido e importe cero';\n\n  -- …modo estricto y diario\n  insert into erp.journal_entries (company_id, fiscal_year_id, posting_date, description)\n  values (e, (select id from erp.fiscal_years where company_id = e and year = 2026), '2026-12-31', 'A mano') returning id into w;\n  insert into erp.journal_lines (entry_id, company_id, line_no, gl_account_id, debit, credit) values\n    (w, e, 1, (select id from erp.gl_accounts where company_id = e and account_no = '67800001'), 10, 0),\n    (w, e, 2, (select id from erp.gl_accounts where company_id = e and account_no = '14200001'), 0, 10);\n  assert public.falla(format('select erp.post_entry(%L); select public.comprueba()', w), 'controlled by provisions'), 'estricto: 142 a mano no';\n  delete from erp.journal_lines where entry_id = w; delete from erp.journal_entries where id = w;\n  assert public.falla(format('select erp.reverse_entry(%L, %L, %L)', (select entry_id from erp.provision_movements where provision_id = lit),\n           '2026-12-31', 'x'), 'belongs to a provision'), 'no se anula desde el diario';\n  raise notice 'OK  · modo estricto: la 142 solo la mueve el módulo; su asiento no se anula desde el diario';\n\n  perform erp.set_control_mode(e, 'guided');   -- v0.41.0: en estricto no se cierra sin el Impuesto sobre Sociedades (aquí no se calcula)\n  perform erp.close_fiscal_year(e, 2026, true);\n  perform erp.set_control_mode(e, 'strict');\n\n  -- ---------- 2. 2027: revisión, aplicación y reclasificación ----------\n  select * into r from erp.revise_provision(jsonb_build_object('provision_id', lit, 'review_date', '2027-12-31', 'new_amount', 15000));\n  assert r.difference = 3000 and public.asiento(e, 2027, r.entry_no) = '67800001 D 3000.00 | 14200001 H 3000.00', public.asiento(e, 2027, r.entry_no);\n  select * into r from erp.revise_provision(jsonb_build_object('provision_id', gar, 'review_date', '2027-12-31', 'new_amount', 1200));\n  assert public.asiento(e, 2027, r.entry_no) = '49990001 D 1000.00 | 79540001 H 1000.00 | 69590001 D 1200.00 | 49990001 H 1200.00',\n         'garantías: se revierte la anterior y se dota la nueva: ' || public.asiento(e, 2027, r.entry_no);\n  select * into r from erp.apply_provision(jsonb_build_object('provision_id', imp, 'application_date', '2027-04-20', 'paid', 3200, 'cash_account_no', '57200001'));\n  assert r.difference = 200 and public.asiento(e, 2027, r.entry_no) = '52920001 D 3000.00 | 63300001 D 200.00 | 57200001 H 3200.00',\n         public.asiento(e, 2027, r.entry_no);\n  assert (select status from erp.provisions where id = imp) = 'applied';\n  assert public.falla(format('select * from erp.revise_provision(%L)', jsonb_build_object('provision_id', imp, 'review_date', '2027-12-31', 'new_amount', 1)),\n           'is not active'), 'aplicada, ya no se revisa';\n  n := erp.reclassify_provision(lit, '2027-12-31');\n  assert public.asiento(e, 2027, n) = '14200001 D 15000.00 | 52930001 H 15000.00', public.asiento(e, 2027, n);\n  assert public.falla(format('select erp.reclassify_provision(%L, %L)', lit, '2027-12-31'), 'already short-term');\n  assert public.falla(format('select * from erp.revise_provision(%L)', jsonb_build_object('provision_id', lit, 'review_date', '2027-12-30', 'new_amount', 1)),\n           'already has a movement after'), 'no se mete un movimiento antes del último';\n  assert public.mov(e, 2027, '678') = 3000 and public.mov(e, 2027, '7954') = -1000 and public.mov(e, 2027, '6959') = 1200\n     and public.mov(e, 2027, '633') = 200, 'gastos e ingresos de 2027';\n  raise notice 'OK  · 2027: litigio +3.000 (678) y a corto plazo (5293); garantías 7954 1.000 / 6959 1.200; acta pagada 3.200 (633 200)';\n\n  -- …deshacer: la reclasificación vuelve a la 142, y se rehace\n  perform erp.cancel_provision_movement(lit);\n  assert (select term || ' ' || provision_account_no from erp.v_provisions where id = lit) = 'long 14200001', 'vuelve al largo plazo';\n  perform erp.reclassify_provision(lit, '2027-12-31');\n  -- …y la aplicación del acta vuelve a dejarla viva\n  perform erp.cancel_provision_movement(imp);\n  assert (select status || ' ' || balance from erp.v_provisions where id = imp) = 'active 3000.00', 'aplicación deshecha';\n  perform erp.apply_provision(jsonb_build_object('provision_id', imp, 'application_date', '2027-04-20', 'paid', 3200, 'cash_account_no', '57200001'));\n  raise notice 'OK  · deshacer el último movimiento (reclasificación, aplicación) y volver a hacerlo';\n\n  perform erp.set_control_mode(e, 'guided');   -- v0.41.0: en estricto no se cierra sin el Impuesto sobre Sociedades (aquí no se calcula)\n  perform erp.close_fiscal_year(e, 2027, true);\n  perform erp.set_control_mode(e, 'strict');\n  assert public.saldo(e, 2027, '142') = 0 and public.saldo(e, 2027, '5293') = -15000 and public.saldo(e, 2027, '4999') = -1200\n     and public.saldo(e, 2027, '5292') = 0, 'saldos al cierre de 2027 (con la apertura): ' || public.saldo(e, 2027, '5293');\n\n  -- ---------- 3. 2028: sentencia ----------\n  select * into r from erp.apply_provision(jsonb_build_object('provision_id', lit, 'application_date', '2028-03-15', 'paid', 14000, 'cash_account_no', '57200001'));\n  assert r.difference = -1000 and public.asiento(e, 2028, r.entry_no) = '52930001 D 15000.00 | 57200001 H 14000.00 | 79530001 H 1000.00',\n         public.asiento(e, 2028, r.entry_no);\n  assert public.saldo(e, 2028, '5293') = 0, 'la 5293 queda a cero';\n  raise notice 'OK  · 2028: sentencia de 14.000 sobre 15.000 provisionados → 1.000 de exceso (7953); la 5293 a cero';\n\n  -- ---------- 4. Invariantes y diario ----------\n  perform public.comprueba();\n  for n in 2026..2028 loop\n    assert not exists (select 1 from erp.integrity_checks(e, n) where status = 'fail'),\n           n || ': ' || (select string_agg(code, ', ') from erp.integrity_checks(e, n) where status = 'fail');\n  end loop;\n  assert (select items from erp.run_audit_checks(e, 2027) where code = 'controlled') = 0, 'los asientos del módulo no son manuales';\n  assert (select count(distinct entry_no) from erp.v_general_journal where company_id = e and fiscal_year = 2026 and source = 'provision') = 3;\n  raise notice 'OK  · invariantes en verde en los tres años; el diario marca las provisiones';\nend $$;\n\n-- ---------- 5. Seguridad ----------\nselect set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-0000000000b2', false) \\gset\ndo $$\ndeclare e uuid := (select v from public.ctx where k = 'empresa');\nbegin\n  assert (select count(*) from erp.v_provisions where company_id = e) = 3, 'el lector ve las provisiones';\n  assert (select jsonb_array_length(movements) from erp.v_provisions where company_id = e and code = 'PRV-0001') = 4, 'con sus movimientos';\n  assert public.falla(format('select * from erp.create_provision(%L)', jsonb_build_object('company_id', e, 'kind', 'commercial',\n           'description', 'X', 'amount', 10, 'provision_date', '2028-12-31')), 'No permission'), 'pero no dota';\n  assert public.falla(format('select erp.provision_post(%L, %L, %L, %L)', e, '2028-12-31', 'x', '[]'), 'permission denied'), 'las ayudas no son públicas';\n  raise notice 'OK  · el lector ve, no dota ni usa las ayudas internas';\nend $$;\n\n-- ---------- 6. Borrar la empresa ----------\nselect set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-0000000000a1', false) \\gset\ndo $$\ndeclare e uuid := (select v from public.ctx where k = 'empresa'); n int;\nbegin\n  loop n := erp.delete_company_step(e, 5); exit when n = 0; end loop;\n  perform public.comprueba();\n  assert not exists (select 1 from erp.companies where id = e);\n  raise notice 'OK  · una empresa con provisiones se borra entera';\nend $$;\n\n\\echo '✔ FASE 40 OK · provisiones'\n",
  "database/tests/test_fase42_inventory_closing.sql": "-- =====================================================================\n-- PRUEBAS FASE 42 · Regularización de existencias y asistente de cierre (migración 0047)\n-- ---------------------------------------------------------------------\n-- SUPUESTO DE REFERENCIA (calculado a mano desde la norma: PGC 2007, NRV 10.ª; cuentas 300, 310, 390, 610, 611, 693 y 793):\n--  Distribuciones Orotava SL (Canarias), 2026 y 2027. Inventario por recuento al cierre (método administrativo).\n--   2026: compra mercaderías por 50.000 (600) y materias primas por 10.000 (601). Al 31/12 el recuento da:\n--         mercaderías 8.000 (a coste), con un valor neto realizable de 7.500 → deterioro 500; materias primas 2.000.\n--         30000001 D 8.000 / 61000001 H 8.000 · 69310001 D 500 / 39000001 H 500 · 31000001 D 2.000 / 61100001 H 2.000\n--         Consumo de mercaderías 2026 = 50.000 − 8.000 = 42.000 (600 + 610).\n--   2027: compra mercaderías por 40.000. Al 31/12: mercaderías 6.000 (sin deterioro) y materias primas 0.\n--         Se da de baja la existencia inicial, de alta la final y se revierte el deterioro del año anterior:\n--         61000001 D 8.000 / 30000001 H 8.000 · 30000001 D 6.000 / 61000001 H 6.000 · 39000001 D 500 / 79310001 H 500\n--         · 61100001 D 2.000 / 31000001 H 2.000\n--         Consumo de mercaderías 2027 = 8.000 + 40.000 − 6.000 = 42.000 (600 40.000 + 610 2.000).\n-- =====================================================================\n\\set ON_ERROR_STOP 1\n\\set QUIET 1\n\ninsert into auth.users (id, email) values ('00000000-0000-0000-0000-0000000000a1', 'admin@test.local');\ninsert into erp.app_profiles (user_id, app_role, max_companies) values ('00000000-0000-0000-0000-0000000000a1', 'owner', null);\n\ncreate or replace function public.falla(sql text, texto text) returns boolean language plpgsql as $$\nbegin\n  execute sql;\n  return false;\nexception when others then\n  if sqlerrm ilike '%' || texto || '%' then return true; end if;\n  raise notice 'error inesperado: %', sqlerrm;\n  return false;\nend $$;\ncreate or replace function public.factura(e uuid, tercero uuid, fecha date, lineas jsonb) returns uuid language sql as $$\n  select invoice_id from erp.post_invoice(jsonb_build_object('company_id', e, 'invoice_type', 'purchase', 'document_kind', 'invoice',\n    'partner_id', tercero, 'external_document_no', 'P-' || substr(md5(random()::text), 1, 8),\n    'invoice_date', fecha, 'description', 'Supuesto', 'lines', lineas));\n$$;\ncreate or replace function public.mov(e uuid, y int, prefijo text) returns numeric language sql as $$\n  select coalesce(sum(l.debit - l.credit), 0) from erp.journal_lines l join erp.journal_entries j on j.id = l.entry_id\n  join erp.fiscal_years fy on fy.id = j.fiscal_year_id and fy.year = y join erp.gl_accounts g on g.id = l.gl_account_id\n  where j.company_id = e and j.status = 'posted' and j.entry_type = 'normal' and g.account_no like prefijo || '%';\n$$;\ncreate or replace function public.saldo(e uuid, y int, prefijo text) returns numeric language sql as $$\n  select coalesce(sum(debit_balance - credit_balance), 0) from erp.trial_balance(e, y) where account_no like prefijo || '%';\n$$;\ncreate or replace function public.asiento(e uuid, y int, n int) returns text language sql as $$\n  select string_agg(g.account_no || ' ' || case when l.debit > 0 then 'D ' || l.debit else 'H ' || l.credit end, ' | ' order by l.line_no)\n  from erp.journal_entries j join erp.fiscal_years fy on fy.id = j.fiscal_year_id and fy.year = y\n  join erp.journal_lines l on l.entry_id = j.id join erp.gl_accounts g on g.id = l.gl_account_id\n  where j.company_id = e and j.entry_no = n;\n$$;\ncreate or replace function public.paso(e uuid, y int, c text) returns text language sql as $$\n  select status from erp.closing_checklist(e, y) where code = c;\n$$;\ncreate or replace function public.comprueba() returns void language plpgsql as $$\nbegin execute 'set constraints all immediate'; execute 'set constraints all deferred'; end $$;\ngrant execute on function public.falla(text, text), public.factura(uuid, uuid, date, jsonb), public.mov(uuid, int, text),\n  public.saldo(uuid, int, text), public.asiento(uuid, int, int), public.paso(uuid, int, text), public.comprueba() to authenticated;\n\nset role authenticated;\nselect set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-0000000000a1', false) \\gset\n\ndo $$\ndeclare e uuid; prov uuid; r record; c uuid; w uuid; q int; s text;\nbegin\n  insert into erp.companies (name, industry, tax_territory, created_by)\n  values ('Distribuciones Orotava SL', 'retail', 'canary_islands', auth.uid()) returning id into e;\n  perform erp.create_fiscal_year(e, 2026); perform erp.create_fiscal_year(e, 2027);\n  perform erp.setup_taxes(e);\n  perform erp.set_control_mode(e, 'strict');\n  perform erp.create_posting_account(e, x.no, x.name) from (values\n    ('60000001', 'Compras de mercaderías'), ('60100001', 'Compras de materias primas'),\n    ('30000001', 'Mercaderías'), ('31000001', 'Materias primas')) as x(no, name);\n  select partner_id into prov from erp.create_partner(e, 'vendor', 'Mayorista Canario SL', 'B12345674');\n\n  -- ---------- 1. El asistente de cierre, al empezar ----------\n  perform public.factura(e, prov, '2026-03-10', '[{\"account_no\":\"60000001\",\"amount\":50000,\"tax_code\":\"IGIC7\"}]');\n  perform public.factura(e, prov, '2026-05-20', '[{\"account_no\":\"60100001\",\"amount\":10000,\"tax_code\":\"IGIC7\"}]');\n  select string_agg(step || ':' || code || '=' || status, ' ' order by step) into s from erp.closing_checklist(e, 2026);\n  assert s = '1:settlements=pending 2:accruals_reversed=done 3:depreciation=na 4:asset_impairment=na 5:accruals=review '\n             '6:bad_debts=done 7:provisions=review 8:inventory=pending 9:audit_checks=done 10:corporate_tax=pending 11:close=pending', s;\n  raise notice 'OK  · asistente de 2026: faltan las liquidaciones, el inventario y el cierre; el resto, revisar o hecho';\n\n  -- ---------- 2. Inventario del 31/12/2026 ----------\n  select string_agg(account_no || ':' || initial_value || '>' || variation_account_no, ' ' order by account_no) into s\n  from erp.inventory_preview(e, '2026-12-31');\n  assert s = '30000001:0>610 31000001:0>611', 'vista previa: ' || s;\n  select * into r from erp.post_inventory(jsonb_build_object('company_id', e, 'count_date', '2026-12-31', 'lines', jsonb_build_array(\n    jsonb_build_object('account_no', '30000001', 'final_value', 8000, 'impairment', 500),\n    jsonb_build_object('account_no', '31000001', 'final_value', 2000))));\n  c := r.count_id;\n  assert r.variation = 10000, 'variación +10.000';\n  assert public.asiento(e, 2026, r.entry_no)\n       = '30000001 D 8000.00 | 61000001 H 8000.00 | 69310001 D 500.00 | 39000001 H 500.00 | 31000001 D 2000.00 | 61100001 H 2000.00',\n         public.asiento(e, 2026, r.entry_no);\n  assert public.mov(e, 2026, '600') + public.mov(e, 2026, '610') = 42000, 'consumo de mercaderías 2026 = 42.000';\n  assert public.falla(format('select * from erp.post_inventory(%L)', jsonb_build_object('company_id', e, 'count_date', '2026-12-31',\n           'lines', '[{\"account_no\":\"30000001\",\"final_value\":1}]'::jsonb)), 'already posted'), 'un inventario por ejercicio';\n  raise notice 'OK  · inventario 2026: 300 8.000 / 610 · deterioro 693 500 / 390 · 310 2.000 / 611; consumo de mercaderías 42.000';\n\n  -- …se deshace y se rehace; no se anula desde el diario; la 300 no se toca a mano\n  assert public.falla(format('select erp.reverse_entry(%L, %L, %L)', (select entry_id from erp.inventory_counts where id = c), '2026-12-31', 'x'),\n           'inventory count'), 'no desde el diario';\n  perform erp.cancel_inventory(c);\n  assert public.saldo(e, 2026, '300') = 0, 'deshecho';\n  perform erp.post_inventory(jsonb_build_object('company_id', e, 'count_date', '2026-12-31', 'lines', jsonb_build_array(\n    jsonb_build_object('account_no', '30000001', 'final_value', 8000, 'impairment', 500),\n    jsonb_build_object('account_no', '31000001', 'final_value', 2000))));\n  insert into erp.journal_entries (company_id, fiscal_year_id, posting_date, description)\n  values (e, (select id from erp.fiscal_years where company_id = e and year = 2026), '2026-12-31', 'A mano') returning id into w;\n  insert into erp.journal_lines (entry_id, company_id, line_no, gl_account_id, debit, credit) values\n    (w, e, 1, (select id from erp.gl_accounts where company_id = e and account_no = '30000001'), 10, 0),\n    (w, e, 2, (select id from erp.gl_accounts where company_id = e and account_no = '61000001'), 0, 10);\n  assert public.falla(format('select erp.post_entry(%L); select public.comprueba()', w), 'controlled by inventory'), 'estricto: 300 a mano no';\n  delete from erp.journal_lines where entry_id = w; delete from erp.journal_entries where id = w;\n  raise notice 'OK  · el inventario se deshace desde el módulo; la 300 no admite asientos manuales (modo estricto)';\n\n  -- ---------- 3. Liquidaciones y cierre: el asistente lo ve ----------\n  for q in 1..4 loop perform erp.post_tax_settlement(e, 'IGIC', 2026, q); end loop;\n  assert public.paso(e, 2026, 'settlements') = 'done' and public.paso(e, 2026, 'inventory') = 'done';\n  perform erp.set_control_mode(e, 'guided');   -- v0.41.0: en estricto no se cierra sin el Impuesto sobre Sociedades (aquí no se calcula)\n  perform erp.close_fiscal_year(e, 2026, true);\n  perform erp.set_control_mode(e, 'strict');\n  assert public.paso(e, 2026, 'close') = 'done';\n  assert public.saldo(e, 2027, '300') = 8000 and public.saldo(e, 2027, '390') = -500 and public.saldo(e, 2027, '310') = 2000, 'apertura de 2027';\n  raise notice 'OK  · asistente: liquidaciones, inventario y cierre hechos; la apertura de 2027 trae 300 8.000, 390 −500 y 310 2.000';\n\n  -- ---------- 4. Inventario del 31/12/2027 ----------\n  perform public.factura(e, prov, '2027-04-15', '[{\"account_no\":\"60000001\",\"amount\":40000,\"tax_code\":\"IGIC7\"}]');\n  assert public.falla(format('select * from erp.post_inventory(%L)', jsonb_build_object('company_id', e, 'count_date', '2027-12-31',\n           'lines', '[{\"account_no\":\"30000001\",\"final_value\":6000}]'::jsonb)), 'Include every stock account with a balance in the count: 31000001'),\n         'hay que contar también las materias primas (aunque sean 0)';\n  select string_agg(account_no || ':' || initial_value || ':' || prev_impairment, ' ' order by account_no) into s from erp.inventory_preview(e, '2027-12-31');\n  assert s = '30000001:8000.00:500.00 31000001:2000.00:0', 'vista previa 2027: ' || s;\n  select * into r from erp.post_inventory(jsonb_build_object('company_id', e, 'count_date', '2027-12-31', 'lines', jsonb_build_array(\n    jsonb_build_object('account_no', '30000001', 'final_value', 6000),\n    jsonb_build_object('account_no', '31000001', 'final_value', 0))));\n  assert public.asiento(e, 2027, r.entry_no)\n       = '61000001 D 8000.00 | 30000001 H 8000.00 | 30000001 D 6000.00 | 61000001 H 6000.00 | 39000001 D 500.00 | 79310001 H 500.00 | 61100001 D 2000.00 | 31000001 H 2000.00',\n         public.asiento(e, 2027, r.entry_no);\n  assert public.mov(e, 2027, '600') + public.mov(e, 2027, '610') = 42000, 'consumo de mercaderías 2027 = 8.000 + 40.000 − 6.000';\n  assert public.saldo(e, 2027, '300') = 6000 and public.saldo(e, 2027, '390') = 0 and public.saldo(e, 2027, '310') = 0;\n  assert public.mov(e, 2027, '793') = -500, 'reversión del deterioro anterior (793)';\n  raise notice 'OK  · inventario 2027: baja de los 8.000 iniciales, alta de los 6.000 finales, 793 500; consumo 42.000';\n\n  -- ---------- 5. Invariantes ----------\n  perform public.comprueba();\n  assert not exists (select 1 from erp.integrity_checks(e, 2026) where status = 'fail');\n  assert not exists (select 1 from erp.integrity_checks(e, 2027) where status = 'fail'),\n         (select string_agg(code, ', ') from erp.integrity_checks(e, 2027) where status = 'fail');\n  assert (select items from erp.run_audit_checks(e, 2027) where code = 'controlled') = 0, 'el inventario no es un asiento manual';\n  assert (select count(distinct entry_no) from erp.v_general_journal where company_id = e and fiscal_year = 2027 and source = 'inventory') = 1;\n  raise notice 'OK  · invariantes en verde; el diario marca el inventario';\nend $$;\n\n\\echo '✔ FASE 42 OK · existencias y asistente de cierre'\n",
  "database/tests/test_fase49_operations_exercises.sql": "-- =====================================================================\n-- PRUEBAS FASE 49 · Catálogo de operaciones y supuestos autocorregidos (migración 0054)\n-- ---------------------------------------------------------------------\n--  · Catálogo: 18 operaciones (17 + el Impuesto sobre Sociedades, 0059) con su pantalla, su asiento modelo y sus fuentes; un asiento dice a qué operación se parece.\n--  · Supuestos: 14, todos con el asiento esperado cuadrado, su explicación, sus fuentes y su concepto del glosario.\n--    Cada uno, contestado bien con subcuentas de 8 dígitos, saca un 100.\n--  · Corrección: lado cambiado, cuenta equivocada (410 en vez de 400), importe mal, asiento descuadrado, cuenta\n--    alternativa (700 en vez de 708), líneas partidas (dos líneas a la 476) y los errores frecuentes explicados.\n--  · Intentos: cada usuario ve los suyos y su progreso; los de la IA aparte.\n-- =====================================================================\n\\set ON_ERROR_STOP 1\n\\set QUIET 1\n\ninsert into auth.users (id, email) values\n  ('00000000-0000-0000-0000-0000000000a1', 'alumno@test.local'),\n  ('00000000-0000-0000-0000-0000000000b2', 'otro@test.local');\n\ncreate or replace function public.falla(sql text, texto text) returns boolean language plpgsql as $$\nbegin\n  execute sql;\n  return false;\nexception when others then\n  if sqlerrm ilike '%' || texto || '%' then return true; end if;\n  raise notice 'error inesperado: %', sqlerrm;\n  return false;\nend $$;\n-- respuesta en jsonb desde texto: '600 D 2000 | 472 D 420 | 400 H 2420'\ncreate or replace function public.resp(t text) returns jsonb language sql as $$\n  select jsonb_agg(jsonb_build_object('account_no', p[1], 'debit', case p[2] when 'D' then p[3]::numeric else 0 end,\n                                      'credit', case p[2] when 'H' then p[3]::numeric else 0 end) order by ord)\n  from unnest(string_to_array(t, ' | ')) with ordinality u(x, ord), string_to_array(u.x, ' ') p;\n$$;\ngrant execute on function public.falla(text, text), public.resp(text) to authenticated;\n\nset role authenticated;\nselect set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-0000000000a1', false) \\gset\n\ndo $$\ndeclare g jsonb; x record; ans jsonb;\nbegin\n  -- ---------- 1. Catálogo ----------\n  assert (select count(*) from erp.operations) = 18 and (select count(*) from erp.exercises) = 16;\n  assert not exists (select 1 from erp.operations o, unnest(o.sources) k where not exists (select 1 from erp.sources s where s.key = k))\n     and not exists (select 1 from erp.exercises o, unnest(o.sources) k where not exists (select 1 from erp.sources s where s.key = k)),\n         'todas las fuentes citadas existen en la base documental';\n  assert (select count(*) from erp.sources) = 16, 'diez fuentes de la v0.39.0 + seis de los supuestos';\n  assert not exists (select 1 from erp.exercises where cardinality(sources) = 0 or concept is null), 'cada supuesto cita su norma y su concepto';\n  assert not exists (select 1 from erp.exercises xx where (select sum((e->>'amount')::numeric) filter (where e->>'side' = 'debit') from jsonb_array_elements(xx.expected) e)\n                                                    <> (select sum((e->>'amount')::numeric) filter (where e->>'side' = 'credit') from jsonb_array_elements(xx.expected) e)),\n         'todos los asientos esperados cuadran';\n  raise notice 'OK  · 18 operaciones y 16 supuestos, con fuentes y concepto; los asientos esperados cuadran';\n\n  -- ---------- 2. ¿Dónde se registra? ----------\n  assert (select key from erp.operation_for_lines(public.resp('60000001 D 100 | 47200021 D 21 | 40000001 H 121'))) = 'purchase_invoice';\n  assert (select key from erp.operation_for_lines(public.resp('60000001 D 100 | 47208021 D 21 | 47708021 H 21 | 40000002 H 100'))) = 'intra_eu_acquisition', 'la más concreta gana';\n  assert (select key || ' ' || screen from erp.operation_for_lines(public.resp('64000001 D 2000 | 64200001 D 640 | 47600001 H 770 | 47510001 H 240 | 46500001 H 1630'))) = 'payroll payroll';\n  assert (select key from erp.operation_for_lines(public.resp('47700021 D 2982 | 47200021 H 2793 | 47500001 H 189'))) = 'tax_settlement';\n  assert (select key || ' ' || screen from erp.operation_for_lines(public.resp('57200001 D 1000 | 43000001 H 1000'))) = 'collection payments';\n  assert (select key || ' ' || screen from erp.operation_for_lines(public.resp('68100001 D 1200 | 28130001 H 1200'))) = 'depreciation assets';\n  assert not exists (select 1 from erp.operation_for_lines(public.resp('62600001 D 10 | 57200001 H 10'))), 'un gasto bancario no tiene módulo';\n  raise notice 'OK  · el asiento propuesto dice su operación y su pantalla (compra, AIB, nómina, liquidación, cobro, amortización)';\n\n  -- ---------- 3. Cada supuesto, bien contestado con subcuentas ----------\n  for x in select * from erp.exercises loop\n    select jsonb_agg(jsonb_build_object('account_no', rpad(e->>'account', 7, '0') || '1',\n             'debit', case e->>'side' when 'debit' then (e->>'amount')::numeric else 0 end,\n             'credit', case e->>'side' when 'credit' then (e->>'amount')::numeric else 0 end)) into ans\n    from jsonb_array_elements(x.expected) e;\n    g := erp.grade_exercise(x.key, ans);\n    assert (g->>'ok')::boolean and (g->>'score')::int = 100, x.key || ': ' || g::text;\n  end loop;\n  raise notice 'OK  · los 16 supuestos, contestados bien con subcuentas de 8 dígitos, sacan un 100';\n\n  -- ---------- 4. Corrección ----------\n  g := erp.grade_exercise('purchase_vat', public.resp('600 D 2000 | 472 H 420 | 400 H 2420'));\n  assert not (g->>'ok')::boolean and g->'lines'->1->>'status' = 'side' and (g->>'balanced')::boolean = false\n     and g->'tips'->0->>'msg' like 'El IVA soportado va al Debe%' and (g->>'score')::int = 67, g::text;\n  g := erp.grade_exercise('purchase_vat', public.resp('600 D 2000 | 472 D 420 | 410 H 2420'));\n  assert g->'lines'->2->>'status' = 'missing' and g->'extra'->0->>'account' = '410' and g->'tips'->0->>'msg' like 'Los proveedores de mercaderías van a la 400%', g::text;\n  g := erp.grade_exercise('purchase_vat', public.resp('600 D 2000 | 472 D 400 | 400 H 2400'));\n  assert g->'lines'->1->>'status' = 'amount' and (g->'lines'->1->>'answered')::numeric = 400 and (g->>'balanced')::boolean, g::text;\n  raise notice 'OK  · lado cambiado (con su explicación), cuenta equivocada (410: falta la 400 y sobra la 410) e importe mal';\n  g := erp.grade_exercise('credit_memo_sale', public.resp('70000001 D 500 | 47700021 D 105 | 43000001 H 605'));\n  assert (g->>'ok')::boolean and (g->'lines'->0->>'alt_used')::boolean, 'la 700 también vale (avisando de la 708): ' || g::text;\n  g := erp.grade_exercise('monthly_payroll', public.resp('640 D 2000 | 642 D 640 | 476 H 130 | 476 H 640 | 4751 H 240 | 465 H 1630'));\n  assert (g->>'ok')::boolean, 'dos líneas a la 476 suman 770: ' || g::text;\n  g := erp.grade_exercise('monthly_payroll', public.resp('640 D 2000 | 642 D 640 | 476 H 770 | 4751 H 240 | 572 H 1630'));\n  assert not (g->>'ok')::boolean and g->'tips'->0->>'msg' like 'El líquido aún no se ha pagado%', g::text;\n  g := erp.grade_exercise('inventory_change', public.resp('610 D 8000 | 300 H 8000 | 300 D 6000 | 610 H 6000'));\n  assert (g->>'ok')::boolean, 'la misma cuenta a los dos lados';\n  g := erp.grade_exercise('inventory_change', public.resp('610 D 2000 | 300 H 2000'));\n  assert not (g->>'ok')::boolean and (g->>'score')::int = 0, 'el neto no vale: hay que dar de baja la inicial y de alta la final';\n  g := erp.grade_exercise('year_end_result', public.resp('70000001 D 65000 | 62900001 H 50000 | 12900001 H 15000'));\n  assert (g->>'ok')::boolean, 'grupos 6 y 7 por el primer dígito';\n  assert public.falla($q$select erp.grade_exercise('no_existe', '[]')$q$, 'not found');\n  raise notice 'OK  · cuenta alternativa (700 por 708), líneas partidas, misma cuenta a los dos lados y grupos 6 / 7';\n\n  -- ---------- 5. Intentos y progreso ----------\n  perform erp.submit_exercise('purchase_vat', public.resp('600 D 2000 | 472 H 420 | 400 H 2420'));\n  perform erp.submit_exercise('purchase_vat', public.resp('600 D 2000 | 472 D 420 | 400 H 2420'));\n  perform erp.submit_exercise('sale_igic', public.resp('430 D 1605 | 700 H 1605'), 'ai');\n  assert (select attempts || ' ' || best_score || ' ' || solved from erp.v_exercise_progress where key = 'purchase_vat') = '2 100 true';\n  assert (select attempts || ' ' || coalesce(ai_score, -1) || ' ' || coalesce(ai_ok::text, '-') from erp.v_exercise_progress where key = 'sale_igic') = '0 33 false',\n         (select attempts || ' ' || coalesce(ai_score, -1) || ' ' || coalesce(ai_ok::text, '-') from erp.v_exercise_progress where key = 'sale_igic');\n  assert (select count(*) from erp.v_exercise_progress) = 16;\n  assert public.falla($q$select erp.submit_exercise('purchase_vat', '[]', 'otro')$q$, 'Invalid attempt');\n  raise notice 'OK  · intentos guardados: dos del alumno (mejor nota 100, resuelto) y uno de la IA (33), aparte';\nend $$;\n\nselect set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-0000000000b2', false) \\gset\ndo $$\nbegin\n  assert (select count(*) from erp.exercise_attempts) = 0, 'otro usuario no ve los intentos ajenos';\n  assert (select sum(attempts) from erp.v_exercise_progress) = 0;\n  assert (select count(*) from erp.exercises) = 16, 'pero sí los supuestos';\n  raise notice 'OK  · cada usuario ve solo sus intentos';\nend $$;\nselect set_config('request.jwt.claim.sub', '', false) \\gset\ndo $$\nbegin\n  assert public.falla($q$select erp.submit_exercise('purchase_vat', '[]')$q$, 'Sign in'), 'sin sesión no se guarda';\n  raise notice 'OK  · sin sesión no se guardan intentos';\nend $$;\n\n\\echo '✔ FASE 49 OK · catálogo de operaciones y supuestos autocorregidos'\n",
  "database/tests/test_fase50_practice_integration.sql": "-- =====================================================================\n-- PRUEBAS FASE 50 · Practicar integrado: evaluar la IA y glosario (migración 0055)\n-- ---------------------------------------------------------------------\n--  · Los intentos de la IA guardan el modelo que contestó; los de las personas, no (aunque lo manden).\n--  · El progreso enseña la nota, el modelo y la fecha del ÚLTIMO intento de la IA, sin mezclarlo con el del alumno.\n--  · submit_exercise rechaza respuestas que no son una lista o que son enormes, y sigue funcionando con 3 argumentos.\n--  · Glosario: «Supuesto práctico» y «Catálogo de operaciones».\n-- =====================================================================\n\\set ON_ERROR_STOP 1\n\\set QUIET 1\n\ninsert into auth.users (id, email) values\n  ('00000000-0000-0000-0000-0000000000a1', 'alumno@test.local'),\n  ('00000000-0000-0000-0000-0000000000b2', 'otro@test.local');\n\ncreate or replace function public.falla(sql text, texto text) returns boolean language plpgsql as $$\nbegin\n  execute sql;\n  return false;\nexception when others then\n  if sqlerrm ilike '%' || texto || '%' then return true; end if;\n  raise notice 'error inesperado: %', sqlerrm;\n  return false;\nend $$;\ncreate or replace function public.resp(t text) returns jsonb language sql as $$\n  select jsonb_agg(jsonb_build_object('account_no', p[1], 'debit', case p[2] when 'D' then p[3]::numeric else 0 end,\n                                      'credit', case p[2] when 'H' then p[3]::numeric else 0 end) order by ord)\n  from unnest(string_to_array(t, ' | ')) with ordinality u(x, ord), string_to_array(u.x, ' ') p;\n$$;\ngrant execute on function public.falla(text, text), public.resp(text) to authenticated;\n\ndo $$\nbegin\n  assert (select count(*) from erp.concepts where key in ('exercise', 'operationCatalog')) = 2;\n  assert (select term from erp.concepts where key = 'operationCatalog') = 'Catálogo de operaciones';\n  assert (select count(*) from pg_proc where proname = 'submit_exercise' and pronamespace = 'erp'::regnamespace) = 1, 'una sola versión de submit_exercise';\n  raise notice 'OK  · glosario con «Supuesto práctico» y «Catálogo de operaciones»; una sola submit_exercise';\nend $$;\n\nset role authenticated;\nselect set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-0000000000a1', false) \\gset\n\ndo $$\ndeclare g jsonb;\nbegin\n  -- el alumno: el modelo no se guarda aunque lo mande; con 3 argumentos sigue funcionando\n  g := erp.submit_exercise('purchase_vat', public.resp('600 D 2000 | 472 D 420 | 400 H 2420'), 'user', 'trampa');\n  assert (g->>'ok')::boolean;\n  perform erp.submit_exercise(p_key => 'sale_igic', p_answer => public.resp('430 D 1605 | 700 H 1500 | 477 H 105'), p_by => 'user');\n  assert (select count(*) from erp.exercise_attempts where by = 'user' and model is null) = 2, 'los intentos del alumno, sin modelo';\n\n  -- la IA: dos intentos del mismo supuesto, con modelos distintos; el progreso enseña el último\n  perform erp.submit_exercise('purchase_vat', public.resp('600 D 2000 | 472 H 420 | 400 H 1580'), 'ai', '@cf/meta/llama-3.3-70b');\n  perform pg_sleep(0.01);\n  perform erp.submit_exercise('purchase_vat', public.resp('60000001 D 2000 | 47200021 D 420 | 40000001 H 2420'), 'ai', '  @cf/openai/gpt-oss-120b  ');\n  assert (select attempts || ' ' || best_score || ' ' || solved || ' · ' || ai_score || ' ' || ai_ok || ' ' || ai_model\n          from erp.v_exercise_progress where key = 'purchase_vat') = '1 100 true · 100 true @cf/openai/gpt-oss-120b',\n         (select row_to_json(p)::text from erp.v_exercise_progress p where key = 'purchase_vat');\n  assert (select ai_at is not null from erp.v_exercise_progress where key = 'purchase_vat');\n  assert (select ai_score is null and ai_model is null and attempts = 1 from erp.v_exercise_progress where key = 'sale_igic'), 'sin intento de la IA: vacío';\n  assert (select count(*) from erp.v_exercise_progress) = 16;\n  raise notice 'OK  · la IA guarda su modelo (sin espacios) y el progreso enseña su último intento; el alumno, sin modelo';\n\n  -- respuestas no válidas\n  assert public.falla($q$select erp.submit_exercise('purchase_vat', '{\"a\": 1}')$q$, 'Invalid answer');\n  assert public.falla($q$select erp.submit_exercise('purchase_vat', (select jsonb_agg(jsonb_build_object('account_no', '600', 'debit', 1)) from generate_series(1, 31)))$q$, 'Invalid answer');\n  assert public.falla($q$select erp.submit_exercise('purchase_vat', '[]', 'robot')$q$, 'Invalid attempt');\n  raise notice 'OK  · se rechazan las respuestas que no son una lista o con más de 30 líneas';\nend $$;\n\nselect set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-0000000000b2', false) \\gset\ndo $$\nbegin\n  assert (select count(*) from erp.v_exercise_progress where ai_score is not null or attempts > 0) = 0, 'otro usuario no ve la evaluación ajena';\n  raise notice 'OK  · cada usuario ve solo su evaluación de la IA';\nend $$;\n\n\\echo '✔ FASE 50 OK · evaluar la IA y glosario de Practicar'\n",
}

if (!fs.existsSync('README.md') || !fs.existsSync('database/migrations')) {
  console.error('✗ Ejecútalo desde la carpeta raíz del proyecto (donde están README.md y database).'); process.exit(1)
}
for (const [p, texto] of Object.entries(FICHEROS)) {
  const actual = fs.existsSync(p) ? fs.readFileSync(p, 'utf8') : null
  if (actual !== null && actual.replace(/\r\n/g, '\n') === texto) { console.log('· ' + p + ' ya estaba'); continue }
  fs.mkdirSync(path.dirname(p), { recursive: true })
  const crlf = actual !== null && actual.includes('\r\n')
  fs.writeFileSync(p, crlf ? texto.replace(/\n/g, '\r\n') : texto)
  console.log('✓ ' + p)
}
console.log('\n✔ Paso 213 aplicado. Ahora ejecuta la migración 0059 en Supabase (SQL Editor).')
